const BOOKS = [
  // FICTION
  { title: "The Midnight Library", author: "Matt Haig", genre: "Fiction", mood: "Thought-Provoking", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780525559474-L.jpg", description: "Between life and death there is a library where every book offers a chance to live a life not chosen.", summary: "Nora Seed finds herself in the Midnight Library — a place between life and death where every book represents a life she could have lived if she'd made different choices. Guided by her old school librarian, she tries on alternate versions of herself: an Olympic swimmer, a glaciologist, a rock musician. The novel is ultimately a meditation on regret, possibility, and the quiet courage it takes to choose your own life. Matt Haig writes with warmth and philosophical depth, making this one of the most resonant novels about the human condition in recent years." },
  { title: "The Alchemist", author: "Paulo Coelho", genre: "Fiction", mood: "Motivational", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780062315007-L.jpg", description: "A young shepherd follows omens across the Sahara, learning that treasure lies where your heart is.", summary: "Santiago, a Spanish shepherd boy, dreams of finding treasure buried near the Egyptian pyramids. On his journey across continents, he encounters a mysterious king, a crystal merchant, an Englishman in search of alchemy, and a desert woman named Fatima. Coelho's fable, translated into over 80 languages, is a gentle but insistent argument that the universe conspires to help those who pursue their Personal Legend. Its prose is simple, its philosophy bold — a book that has changed how millions of readers think about ambition, fate, and the courage to follow one's heart." },
  { title: "The Kite Runner", author: "Khaled Hosseini", genre: "Fiction", mood: "Emotional", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9781594631931-L.jpg", description: "A story of friendship, betrayal, and redemption set against the backdrop of Afghanistan.", summary: "Amir, the son of a wealthy Kabul merchant, and Hassan, the son of his Hazara servant, share a childhood of kite-fighting tournaments and storytelling — until a single act of cowardice on Amir's part destroys everything. Decades later, living in America after the Soviet invasion, Amir receives a call that offers him a chance to go back and make things right. Set against the turbulent history of Afghanistan, Hosseini's debut novel is a shattering exploration of guilt, loyalty, class, and the possibility of redemption when you have done something genuinely unforgivable." },
  { title: "Life of Pi", author: "Yann Martel", genre: "Fiction", mood: "Adventure", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9780156027328-L.jpg", description: "A young boy survives a shipwreck and spends 227 days on a lifeboat with a Bengal tiger.", summary: "After a cargo ship sinks in the Pacific, Pi Patel — a sixteen-year-old Indian boy who simultaneously practices Hinduism, Islam, and Christianity — finds himself alone on a lifeboat with a 450-pound Bengal tiger named Richard Parker. What follows is a remarkable survival story that is also a profound meditation on faith, storytelling, and the nature of reality. Martel's novel asks whether a story that is more beautiful but less literal can still be true — and leaves the answer, generously, for the reader to decide." },
  { title: "The Book Thief", author: "Markus Zusak", genre: "Fiction", mood: "Emotional", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780375842207-L.jpg", description: "Narrated by Death, this is the story of a young girl in Nazi Germany who steals books.", summary: "Set in a small German town during World War II, The Book Thief is narrated by Death, who is drawn to nine-year-old Liesel Meminger — a girl who steals books and shares them with the Jewish man her family is hiding in their basement. Zusak's novel is formally daring and emotionally devastating, combining whimsy and horror in a way that illuminates the power of words to sustain people through the worst of times. It is a book about books, about the strange human compulsion to tell stories even in the middle of catastrophe." },
  { title: "A Little Life", author: "Hanya Yanagihara", genre: "Fiction", mood: "Emotional", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780804172707-L.jpg", description: "A shattering portrait of the enduring bonds of friendship and the traumas that shape a life.", summary: "Four friends — Willem, JB, Malcolm, and Jude — move to New York City after college to pursue their dreams. Over the following decades, the novel narrows its focus to Jude St. Francis, whose childhood has left him with injuries, both physical and psychological, that he has never shared with anyone. Yanagihara's massive novel is one of the most intense reading experiences in contemporary fiction: a book that asks how much suffering the human body and spirit can absorb, and what friendship can and cannot heal. It is not an easy read, but for many readers it is an unforgettable one." },
  { title: "Normal People", author: "Sally Rooney", genre: "Fiction", mood: "Emotional", rating: 4.0, image: "https://covers.openlibrary.org/b/isbn/9780571334650-L.jpg", description: "Two Irish students navigate love, class, and connection through their college years.", summary: "Connell and Marianne grow up in the same small Irish town but inhabit entirely different social worlds — until a careful, tentative connection forms between them that neither can fully admit or sustain. Rooney follows them through their college years at Trinity Dublin as they circle each other, drift apart, hurt each other, and return again. It is a novel about power and vulnerability in intimate relationships, about how people communicate and fail to communicate, and about the particular loneliness of being smart and young and not quite knowing how to live." },
  { title: "Piranesi", author: "Susanna Clarke", genre: "Fiction", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781635575637-L.jpg", description: "In a labyrinthine house of endless halls and statues, Piranesi explores a mysterious world.", summary: "Piranesi lives in a House of infinite halls filled with tidal waters and thousands of stone statues. He knows the House intimately — its tides, its birds, its 13 skeletons — and shares it with only one other living person. But his journals reveal gaps in his memory, and something important has been hidden from him. Clarke's second novel, far shorter than Jonathan Strange but no less strange, is a puzzle-box mystery and a philosophical fable about identity, reality, and the strangeness of consciousness. Its originality is absolute." },
  { title: "The Remains of the Day", author: "Kazuo Ishiguro", genre: "Fiction", mood: "Thought-Provoking", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780679731726-L.jpg", description: "An English butler reflects on a life of dignified service and the opportunities he let slip away.", summary: "Stevens, the consummate English butler, takes a rare motoring holiday through the West Country and uses the journey to reflect on his 35 years of service at Darlington Hall. As he remembers his professional triumphs and his relationship with the former housekeeper Miss Kenton, it slowly becomes clear how much of his inner life he has suppressed in service of an ideal of professionalism — and how much he has lost as a result. Ishiguro's Booker Prize-winning novel is a masterpiece of controlled understatement, a devastating portrait of self-deception told by a man who cannot quite see his own tragedy." },
  { title: "Flowers for Algernon", author: "Daniel Keyes", genre: "Fiction", mood: "Emotional", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780156030304-L.jpg", description: "A man with an intellectual disability undergoes an experiment to increase his intelligence with profound consequences.", summary: "Charlie Gordon, a 32-year-old man with an IQ of 68, volunteers for an experimental surgical procedure that triples his intelligence. Told through Charlie's progress reports — which evolve from barely legible to eloquent as his mind expands — the novel tracks his journey from intellectual disability to genius and back again. Keyes' story raises profound questions about what it means to be human, what intelligence is worth, and whether the people around us see us for who we are or only for what we can offer them. The ending is among the most affecting in American fiction." },

  // FANTASY
  { title: "The Name of the Wind", author: "Patrick Rothfuss", genre: "Fantasy", mood: "Adventure", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780756404741-L.jpg", description: "The legendary Kvothe recounts his life as a wizard from humble orphan to famous hero.", summary: "Kvothe — wizard, musician, thief, and legend — has retired to a quiet inn under a false name. When a Chronicler arrives to record his story, Kvothe agrees to tell it over three days. Book one follows his childhood among a troupe of travelling performers, the catastrophe that destroys his family, his years as a street orphan in Tarbean, and his admission to the University where he studies naming magic. Rothfuss writes with exceptional craft; his prose is beautiful and his storytelling instincts are near-perfect. A deeply immersive opening to one of fantasy's most celebrated series." },
  { title: "Harry Potter and the Sorcerer's Stone", author: "J.K. Rowling", genre: "Fantasy", mood: "Adventure", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780590353427-L.jpg", description: "An orphan boy discovers he is a wizard and is whisked away to Hogwarts School.", summary: "Harry Potter has spent ten years living in a cupboard under the stairs in his aunt and uncle's house, knowing nothing of his famous parents or his own identity — until a flood of letters arrives on his eleventh birthday and a giant named Hagrid appears to deliver the news: Harry is a wizard. The world of Hogwarts — with its moving staircases, talking portraits, Quidditch matches, and hidden dangers — is built with extraordinary imaginative richness. More than a children's book, it is a story about friendship, bravery, and the choice to do what is right when it is hard." },
  { title: "A Court of Thorns and Roses", author: "Sarah J. Maas", genre: "Fantasy", mood: "Romantic", rating: 4.1, image: "https://covers.openlibrary.org/b/isbn/9781619634442-L.jpg", description: "A huntress is dragged into a treacherous magical world — a retelling of Beauty and the Beast.", summary: "Feyre, a mortal huntress struggling to keep her family alive, kills a wolf in the forest — and is taken by a faerie named Tamlin to live in the magical land of Prythian as payment for the act. What begins as captivity slowly becomes something more complicated, as Feyre uncovers the curse that has darkened Prythian and discovers feelings she cannot explain. Maas weaves a dark, sensual retelling of Beauty and the Beast into an epic fantasy world of dangerous faerie courts, ancient magic, and political intrigue that deepens significantly in later volumes." },
  { title: "The Hobbit", author: "J.R.R. Tolkien", genre: "Fantasy", mood: "Adventure", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780345339683-L.jpg", description: "Bilbo Baggins is swept into an epic quest to reclaim the Lonely Mountain from a dragon.", summary: "Bilbo Baggins of Bag End is a hobbit who wants nothing more than a quiet life with his pipe and his pantry — until the wizard Gandalf and thirteen dwarves appear at his door and sweep him into an adventure to recover the dwarves' mountain home from the dragon Smaug. Tolkien's children's novel, which preceded and laid the groundwork for The Lord of the Rings, is a perfect adventure story: episodic, funny, thrilling, and unexpectedly moving. It introduced the world to Middle-earth and established the template for modern fantasy." },
  { title: "Mistborn: The Final Empire", author: "Brandon Sanderson", genre: "Fantasy", mood: "Adventure", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780765311788-L.jpg", description: "In a world of ash and mist, a street thief discovers rare magical powers and joins a rebellion.", summary: "In a world where ash falls from the sky and mists rule the night, the immortal Lord Ruler has reigned for a thousand years. Vin, a young street thief, discovers she possesses Allomancy — the ability to ingest and burn metals to gain supernatural powers. Recruited by a charismatic criminal mastermind named Kelsier, she joins a heist planned not to steal gold but to topple an empire. Sanderson's magic system is intricate and satisfying, his plotting is relentless, and his world-building is some of the richest in epic fantasy." },
  { title: "The Way of Kings", author: "Brandon Sanderson", genre: "Fantasy", mood: "Adventure", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780765326355-L.jpg", description: "An epic tale of war, magic, and destiny on a stormswept alien world.", summary: "The first book in the Stormlight Archive, Sanderson's most ambitious series, follows three main characters: Kaladin, a soldier who has been enslaved and must find a reason to keep fighting; Shallan, a scholar's ward trying to steal a book to save her family; and Dalinar, a highprince who receives strange visions and questions his own sanity. Set on the storm-lashed world of Roshar, with its alien flora and fauna and an elaborate magic system tied to ancient spren spirits, The Way of Kings is one of the most carefully constructed epic fantasies ever written." },
  { title: "Red Rising", author: "Pierce Brown", genre: "Fantasy", mood: "Adventure", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780804139021-L.jpg", description: "A miner born in the lowest caste infiltrates the ruling class to tear their world apart.", summary: "Darrow is a Red — a member of the lowest caste in a rigidly colour-coded future society, living underground on Mars and believing his toil is making the surface habitable. When he discovers the brutal truth of his world, he is given a chance to infiltrate the Gold ruling class by passing as one of them. Brown's debut novel combines futuristic world-building with the structure of Hunger Games-style survival competition and the moral complexity of a revenge narrative. It is relentlessly propulsive, politically intelligent, and impossible to put down." },
  { title: "The Night Circus", author: "Erin Morgenstern", genre: "Fantasy", mood: "Romantic", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780307744432-L.jpg", description: "Two young magicians compete inside a mysterious black-and-white circus open only at night.", summary: "Le Cirque des Rêves appears without warning, open only at night, and everything within it is black and white. Two young magicians — Celia and Marco — have been bound since childhood to a competition whose rules neither fully understands. As they create increasingly spectacular wonders within the circus, they also fall in love, not realising that the competition can have only one survivor. Morgenstern's novel is sumptuous and dreamlike, more interested in atmosphere than plot, and the circus itself — tent by tent — is one of the most beautiful settings in recent fantasy." },
  { title: "Circe", author: "Madeline Miller", genre: "Fantasy", mood: "Thought-Provoking", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780316556347-L.jpg", description: "The legendary witch Circe hones her powers and encounters gods, heroes, and monsters.", summary: "Born to the sun god Helios, Circe lacks both her father's divine power and her mother's nymph beauty. She discovers, through loneliness and experimentation, that she possesses a talent for witchcraft — and is exiled to a remote island as a result. Over centuries she encounters Prometheus, the Minotaur, Daedalus, Medea, and Odysseus. Miller retells the Greek myths from the perspective of a woman who has been marginalised and dismissed, transforming Circe from a minor villain into a fully realised, deeply modern heroine. Her prose is precise, sensuous, and quietly furious." },
  { title: "The Lies of Locke Lamora", author: "Scott Lynch", genre: "Fantasy", mood: "Adventure", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780553588941-L.jpg", description: "A gang of con men pulls off elaborate heists in a crime-lord city in a rich fantasy world.", summary: "In the city of Camorr — a Venice-like labyrinth of canals, towers, and crime — Locke Lamora leads the Gentleman Bastards, a gang of thieves who operate under the noses of both the criminal underworld and the city's nobility. Their elaborate cons are interrupted when a mysterious figure called the Grey King begins murdering crime lords and threatens to destroy everything Locke has built. Lynch's debut is funny, foul-mouthed, and astonishingly inventive, with one of the most compelling anti-heroes in modern fantasy and a plot that delivers surprise after surprise." },
  { title: "Throne of Glass", author: "Sarah J. Maas", genre: "Fantasy", mood: "Adventure", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9781619630345-L.jpg", description: "A young assassin competes to become the king's champion in a deadly tournament.", summary: "Celaena Sardothien is the kingdom's most feared assassin — currently serving a sentence in the salt mines of Endovier. When the Crown Prince offers her a chance at freedom in exchange for competing to become the king's champion, she accepts. The tournament is more dangerous than it appears, as competitors begin dying in mysterious ways, and Celaena discovers an ancient evil beneath the castle. The first book in a massive series, Throne of Glass establishes Maas's signature combination of action, romance, and political intrigue, with a fierce, clever heroine at its centre." },

  // THRILLER
  { title: "Gone Girl", author: "Gillian Flynn", genre: "Thriller", mood: "Dark", rating: 4.1, image: "https://covers.openlibrary.org/b/isbn/9780307588371-L.jpg", description: "On a summer morning a wife vanishes. Her husband's alibi falls apart. Every secret has a price.", summary: "On the morning of Nick and Amy Dunne's fifth wedding anniversary, Amy disappears. As Nick becomes the prime suspect, Flynn alternates between his present-day account and Amy's past diary entries — slowly revealing that neither narrator is telling the full truth. Gone Girl is a razor-sharp dissection of marriage, media, and the performances people put on for each other. Its central twist is one of the most audacious in recent thriller fiction, and Flynn's writing is consistently brilliant: dark, funny, and mercilessly intelligent about gender dynamics and the lies couples tell themselves." },
  { title: "The Silent Patient", author: "Alex Michaelides", genre: "Thriller", mood: "Dark", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9781250301697-L.jpg", description: "A world-famous painter shoots her husband and never speaks again. A psychotherapist becomes obsessed with finding out why.", summary: "Alicia Berenson was a celebrated painter living an apparently perfect life with her fashion photographer husband — until she shot him five times and never spoke another word. Years later, criminal psychotherapist Theo Faber manoeuvres himself into Alicia's secure psychiatric unit, convinced he can unlock her silence. Michaelides' debut thriller is constructed with exceptional skill, building its suspense through Theo's obsessive investigation and Alicia's diary entries. The final revelation reframes everything that has come before and leaves most readers immediately wanting to re-read from the beginning." },
  { title: "Verity", author: "Colleen Hoover", genre: "Thriller", mood: "Dark", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781538724736-L.jpg", description: "A writer discovers a manuscript containing terrifying confessions — but is it fiction or truth?", summary: "Struggling author Lowen Ashby is hired to complete the remaining books in bestselling thriller writer Verity Crawford's series after Verity is incapacitated. While working in the Crawford home, Lowen discovers a manuscript — apparently Verity's autobiography — containing horrifying confessions about her children. As Lowen grows closer to Verity's husband Jeremy, she must decide: is the manuscript the truth, or an elaborate fiction? Hoover delivers one of her most disturbing novels, a psychological thriller with a deeply unsettling ending that has generated passionate debate among readers about what actually happened." },
  { title: "The Girl with the Dragon Tattoo", author: "Stieg Larsson", genre: "Thriller", mood: "Dark", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780307454546-L.jpg", description: "A journalist and a hacker investigate a 40-year-old disappearance in a wealthy family.", summary: "Disgraced journalist Mikael Blomkvist is hired by an elderly industrialist to investigate the decades-old disappearance of his great-niece from a remote family island. He is assisted by Lisbeth Salander, a brilliant, antisocial hacker with a photographic memory and a traumatic past. Larsson's thriller is dense and slow-burning in the best possible way, rewarding patience with one of the most satisfying mysteries in crime fiction. Lisbeth Salander — unconventional, fierce, and deeply moral in her own way — is one of the most memorable characters in modern thriller fiction." },
  { title: "Big Little Lies", author: "Liane Moriarty", genre: "Thriller", mood: "Suspenseful", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9780399167065-L.jpg", description: "Three women at a school trivia night unravel a thread of dark secrets, lies, and hidden violence.", summary: "Three women — Madeline, Celeste, and Jane — meet through their children's school in a wealthy coastal town. When a fatal incident occurs at the school's trivia night, the story unravels backwards through interviews with parents, revealing the hidden lives behind the polished surfaces. Moriarty is exceptional at dissecting social dynamics — the competitiveness of school gates, the way domestic abuse hides in plain sight — and wrapping her insights in a compulsively readable plot. The novel is funny and devastating in equal measure." },
  { title: "In the Woods", author: "Tana French", genre: "Thriller", mood: "Dark", rating: 4.1, image: "https://covers.openlibrary.org/b/isbn/9780670038602-L.jpg", description: "A Dublin detective investigates a murder near the woods where his childhood friends vanished.", summary: "Dublin Murder Squad detective Rob Ryan has a secret: as a child, he and two friends entered the woods near his home and only he emerged — with no memory of what happened and blood in his shoes. Years later, a child's body is found in the same woods, and Rob is assigned the case. French's debut novel is atmospheric and psychologically complex, as interested in Rob's unreliable narration as in the mystery itself. It doesn't deliver the tidy resolution that genre conventions promise, which makes it both maddening and unforgettable — a literary thriller of the highest order." },
  { title: "The Woman in the Window", author: "A.J. Finn", genre: "Thriller", mood: "Suspenseful", rating: 3.9, image: "https://covers.openlibrary.org/b/isbn/9780062678416-L.jpg", description: "An agoraphobic woman spies on her neighbors and witnesses something she was never meant to see.", summary: "Dr. Anna Fox, a child psychologist, hasn't left her Manhattan brownstone in months. She spends her days watching her neighbours through her windows, drinking too much wine, and video-chatting with strangers. When a new family moves in across the park, she becomes fascinated by them — until she witnesses something through the glass that convinces her a crime has been committed. A deliberate homage to Hitchcock's Rear Window and classic women-in-peril thrillers, The Woman in the Window is a twisty, atmospheric page-turner." },
  { title: "Behind Closed Doors", author: "B.A. Paris", genre: "Thriller", mood: "Dark", rating: 4.0, image: "https://covers.openlibrary.org/b/isbn/9781250121004-L.jpg", description: "The perfect marriage hides a perfect nightmare. No couple is ever as happy as they appear.", summary: "Jack and Grace Angel appear to have a perfect life: a beautiful home, elegant dinner parties, a devoted relationship. Their friends envy them. But Grace is never seen alone, never has a phone, and seems to need permission for everything. Paris strips away the perfect surface to reveal a marriage built on coercive control and terror, with a villain of exceptional calculation. A domestic psychological thriller that is tightly constructed and genuinely chilling in its depiction of how abusive relationships are concealed from the outside world." },
  { title: "The Guest List", author: "Lucy Foley", genre: "Thriller", mood: "Suspenseful", rating: 4.0, image: "https://covers.openlibrary.org/b/isbn/9780062868930-L.jpg", description: "At a glamorous wedding on a remote island, one of the guests is found dead.", summary: "A glamorous wedding on a wild, remote island off the Irish coast. The bride is a successful podcast entrepreneur; the groom is a TV celebrity. Their guests — best man, bridesmaid, plus-ones, wedding planner — all have secrets. When a storm cuts off the island and a body is discovered, it becomes clear that almost anyone in attendance had a reason to want someone dead. Foley builds her ensemble thriller with multiple narrators converging on the same night from different angles, deploying red herrings expertly and delivering a satisfying resolution." },
  { title: "Shutter Island", author: "Dennis Lehane", genre: "Thriller", mood: "Dark", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9780062024022-L.jpg", description: "Two U.S. marshals investigate the disappearance of a patient from a hospital for the criminally insane.", summary: "In 1954, U.S. Marshal Teddy Daniels arrives at Ashecliffe Hospital for the Criminally Insane on Shutter Island to investigate the impossible escape of a patient — a woman convicted of drowning her three children. But as a hurricane traps him on the island and his investigation deepens, Teddy begins to question the nature of reality itself. Lehane's novel is a masterful exercise in psychological suspense that works equally well as a thriller and as a meditation on trauma and self-deception. The ending recontextualises everything, demanding an immediate re-read." },

  // ROMANCE
  { title: "Pride and Prejudice", author: "Jane Austen", genre: "Romance", mood: "Happy", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780141439518-L.jpg", description: "Elizabeth Bennet's witty journey toward self-discovery and love with the brooding Mr. Darcy.", summary: "The Bennet family has five daughters to marry off, a limited fortune, and an entailed estate that will pass to a distant cousin. When the wealthy Mr. Bingley arrives in the neighbourhood with his even wealthier friend Mr. Darcy, the matchmaking begins. Austen's most beloved novel is a comedy of manners, a social satire, and a deeply insightful portrait of what it means to truly know another person — and oneself. Elizabeth Bennet, with her intelligence, wit, and fierce independence, remains one of literature's most irresistible heroines more than two centuries after her creation." },
  { title: "It Ends with Us", author: "Colleen Hoover", genre: "Romance", mood: "Emotional", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9781501110368-L.jpg", description: "A heartbreaking story about love, strength, and the most difficult decisions in life.", summary: "Lily Bloom moves to Boston after college with dreams of opening a flower shop, and meets Ryle, a neurosurgeon who seems perfect in every way. As their relationship deepens, Lily finds herself comparing it to her first love — Atlas, a homeless teen she once sheltered — and grappling with painful patterns she recognises from her own childhood. Hoover's novel is unusual in the romance genre for the seriousness with which it engages with domestic abuse, exploring how love and violence can coexist and what real strength looks like when everything you believed in fractures." },
  { title: "The Hating Game", author: "Sally Thorne", genre: "Romance", mood: "Happy", rating: 4.1, image: "https://covers.openlibrary.org/b/isbn/9780062439598-L.jpg", description: "Two office rivals begin to realise their feelings may be something other than hatred.", summary: "Lucy Hutton and Joshua Templeman share an office and an intense mutual dislike. Their publishing company has merged, they are both in the running for the same promotion, and they have an elaborate set of passive-aggressive games with which they torment each other daily. Thorne's debut romance is a textbook enemies-to-lovers story, executed with exceptional charm and wit. The tension between Lucy and Josh crackles on every page, the banter is genuinely funny, and the emotional payoff is enormously satisfying — a near-perfect example of its genre." },
  { title: "Outlander", author: "Diana Gabaldon", genre: "Romance", mood: "Adventure", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780440212560-L.jpg", description: "A WWII nurse is transported to 18th-century Scotland and falls for a dashing warrior.", summary: "In 1945, English nurse Claire Randall is on a second honeymoon in Scotland when she touches an ancient standing stone and is transported to 1743 — the midst of Jacobite uprisings, English soldiers, and a very different world. To survive, she must marry the young Scottish warrior Jamie Fraser, and what begins as a marriage of necessity becomes something far more complicated. Gabaldon's epic combines historical adventure, time-travel mystery, and passionate romance with meticulous period research. The first book in a series of nine, it launched one of the most devoted fanbases in modern fiction." },
  { title: "Me Before You", author: "Jojo Moyes", genre: "Romance", mood: "Emotional", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780143124542-L.jpg", description: "A small-town woman takes a job caring for a fiercely independent man — and both their worlds change.", summary: "Louisa Clark, unemployed and lacking obvious direction, takes a job caring for Will Traynor — a wealthy, sardonic man left quadriplegic after an accident. Will is determined to end his life; Louisa is determined to show him it's worth living. What unfolds is a romance of exceptional emotional intelligence, a story that refuses to simplify either character's position or offer easy consolation. Moyes writes about disability, autonomy, and the right to make one's own choices with a seriousness rare in popular fiction, and the result is a love story that is genuinely devastating." },
  { title: "The Notebook", author: "Nicholas Sparks", genre: "Romance", mood: "Romantic", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9780446605236-L.jpg", description: "A summer love story spanning decades, told through a yellowed notebook read to a woman with dementia.", summary: "An old man reads to a woman with dementia from a faded notebook — the story of Noah and Allie, two teenagers who fall desperately in love one summer in 1940s North Carolina before class divisions and the war tear them apart. Sparks' debut novel established the template for his enormously popular brand of romantic fiction: beautiful settings, uncomplicated prose, sweeping emotion, and a devotion to love as the supreme human experience. The framing narrative, with its bittersweet revelation about the couple's present-day identities, gives the story a depth that transcends the summer-romance plot." },
  { title: "Beach Read", author: "Emily Henry", genre: "Romance", mood: "Happy", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9781984806734-L.jpg", description: "Two rival authors spend a summer challenging each other to write outside their genres and fall in love.", summary: "January Andrews writes happy love stories; Augustus Everett writes literary fiction about human misery. They ended up as neighbours in adjacent lake houses and make a wager: each will write a book in the other's genre by summer's end. January will write something dark and literary; Gus will write a romance with a happy ending. As they research their projects together, they discover that the other's worldview might not be as wrong as they assumed. Henry's novel is the perfect blend of witty banter, genuine emotional depth, and a love story that earns its happy ending." },
  { title: "The Kiss Quotient", author: "Helen Hoang", genre: "Romance", mood: "Happy", rating: 4.0, image: "https://covers.openlibrary.org/b/isbn/9780451490704-L.jpg", description: "A woman with autism hires a professional escort to teach her about relationships.", summary: "Stella Lane, an econometrician with autism, is excellent at her work and bewildered by intimacy. Following her mother's gentle pressure to date more, she hires escort Michael Pham to teach her the skills she lacks. Michael, a part-Vietnamese man with his own complicated family situation, agrees to a professional arrangement that quickly becomes something neither of them expected. Hoang's novel is a charming reversal of the Pretty Woman trope, notable for its sensitive, insider portrayal of autism and its genuine warmth. A romance that is both funny and unexpectedly moving." },
  { title: "People We Meet on Vacation", author: "Emily Henry", genre: "Romance", mood: "Happy", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781984806758-L.jpg", description: "Two best friends share annual vacations until one trip breaks their friendship — years later, they try again.", summary: "Alex and Poppy have been best friends for a decade, spending every summer on a trip together despite being complete opposites. Two years ago, something happened on one of those trips that ended their friendship. Now, Poppy has convinced Alex to give her one more week — one last vacation to figure out whether what they had can be recovered. Henry structures the novel in alternating timelines, building the past relationship alongside the fraught present one, creating a slow-burn romance of enormous emotional richness. A masterclass in the friends-to-lovers trope." },
  { title: "Icebreaker", author: "Hannah Grace", genre: "Romance", mood: "Happy", rating: 4.1, image: "https://covers.openlibrary.org/b/isbn/9781665955324-L.jpg", description: "A figure skater and a hockey player are forced to share an ice rink — and feelings grow.", summary: "Anastasia Allen, a competitive figure skater with Olympic dreams, has the ice rink to herself for early morning practice — until the Maple Hills hockey team, banned from their own rink, is given access to hers. Captain Nathan Hawkins and Anastasia clash immediately over schedules and space, but an unlikely friendship develops, complicated by rules about relationships between athletes. Grace's New Adult romance delivers charming characters, genuine athletic detail, and a slow-burn romance with real emotional stakes. The hockey and skating scenes are written with affectionate authenticity." },

  // SELF-HELP
  { title: "Atomic Habits", author: "James Clear", genre: "Self-Help", mood: "Motivational", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780735211292-L.jpg", description: "An easy and proven way to build good habits and break bad ones through marginal gains.", summary: "James Clear argues that remarkable results come from the compound effect of tiny daily habits — not dramatic transformations. Drawing on research from biology, psychology, and neuroscience, he outlines a practical framework for building good habits and breaking bad ones: make it obvious, make it attractive, make it easy, make it satisfying. The book is structured around the concept of identity-based change — becoming the kind of person who does a thing, rather than merely trying to achieve a goal. Consistently actionable and thoroughly researched, it is one of the most practically useful self-help books published in the last decade." },
  { title: "Thinking, Fast and Slow", author: "Daniel Kahneman", genre: "Self-Help", mood: "Thought-Provoking", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780374533557-L.jpg", description: "Nobel Prize winner explains the two systems that drive our thinking — fast intuitive and slow deliberate.", summary: "Kahneman, the Nobel Prize-winning psychologist, presents his life's work in accessible form: the idea that human cognition operates through two systems. System 1 is fast, intuitive, and emotional; System 2 is slow, deliberate, and logical. Most of our errors in judgement come from System 1's overconfidence and System 2's laziness. Through dozens of experiments and examples, Kahneman reveals the systematic biases that affect our decisions about money, risk, happiness, and other people. Dense but endlessly fascinating, this book permanently changes how you understand your own mind." },
  { title: "Ikigai", author: "Hector Garcia", genre: "Self-Help", mood: "Motivational", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9780143130727-L.jpg", description: "The Japanese secret to a long and happy life — finding your reason for being.", summary: "Ikigai is the Japanese concept of 'reason for being' — the intersection of what you love, what you're good at, what the world needs, and what you can be paid for. Garcia and Miralles travelled to Ogimi, Okinawa — home to some of the world's longest-lived people — to understand what sustained them. The resulting book is short, gentle, and philosophical: not a productivity manual but a meditation on purposeful living, community, staying active, and finding meaning in small pleasures. A calming antidote to hustle culture, it has become a global bestseller for its quiet wisdom." },
  { title: "The Psychology of Money", author: "Morgan Housel", genre: "Self-Help", mood: "Thought-Provoking", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780857197689-L.jpg", description: "Timeless lessons on wealth, greed, and happiness — how psychology drives financial decisions.", summary: "Housel argues that financial success has less to do with intelligence or information than with behaviour — and that behaviour is driven by psychology. In nineteen short chapters, each built around a key insight, he explores themes like the role of luck and risk, the seductive power of compounding, the difference between being wealthy and looking wealthy, and the relationship between money and freedom. Written in clear, story-driven prose and free of financial jargon, The Psychology of Money is the rare personal finance book that is genuinely enjoyable to read, with ideas that stick long after you've finished it." },
  { title: "Deep Work", author: "Cal Newport", genre: "Self-Help", mood: "Motivational", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9781455586691-L.jpg", description: "Rules for focused success in a distracted world — the ability to focus is the new superpower.", summary: "Newport defines deep work as professional activity performed in a state of distraction-free concentration that pushes your cognitive capabilities to their limit. He argues that this ability is both increasingly rare and increasingly valuable, and that those who cultivate it will thrive in the new economy while those who don't will fall behind. The book divides into two parts: a philosophical case for why deep work matters and a practical guide for how to restructure your life to do more of it. Challenging but actionable, it has become essential reading for anyone trying to do meaningful intellectual work in a fragmented world." },
  { title: "The 7 Habits of Highly Effective People", author: "Stephen R. Covey", genre: "Self-Help", mood: "Motivational", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780743269513-L.jpg", description: "A principle-centred approach for solving personal and professional problems with fairness and integrity.", summary: "First published in 1989, Covey's landmark book has sold over 40 million copies for good reason: its framework for effectiveness is principle-based rather than technique-based, meaning its insights don't date. The seven habits progress from personal independence (be proactive, begin with the end in mind, put first things first) to interdependence (think win-win, seek first to understand, synergise) to continuous renewal (sharpen the saw). Dense with ideas and illustrative examples, it rewards slow, reflective reading and has shaped the thinking of leaders, educators, and individuals worldwide." },
  { title: "Man's Search for Meaning", author: "Viktor E. Frankl", genre: "Self-Help", mood: "Inspiring", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780807014271-L.jpg", description: "A Holocaust survivor's account of finding meaning in the most horrific circumstances imaginable.", summary: "Psychiatrist Viktor Frankl survived four Nazi concentration camps, including Auschwitz, and emerged with the core insight that drove his therapeutic approach: that the primary human drive is not pleasure or power but the search for meaning. In the first part of the book, he describes his camp experiences with devastating clarity. In the second, he outlines logotherapy — his therapeutic method built on the conviction that people can endure almost any suffering if they understand why they are enduring it. Brief, honest, and profoundly moving, this is one of the most important books of the twentieth century." },
  { title: "The Power of Now", author: "Eckhart Tolle", genre: "Self-Help", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781577311522-L.jpg", description: "A guide to spiritual enlightenment through living in the present moment, free from past or future.", summary: "Tolle's transformative book grew out of a sudden spiritual awakening he experienced at twenty-nine, when a shift in perception dissolved a lifetime of depression and anxiety. He argues that the source of human suffering is identification with the thinking mind — the constant internal narrator that lives in the past or future — and that liberation comes from learning to inhabit the present moment fully. Written in a question-and-answer format that makes its sometimes challenging concepts more accessible, The Power of Now has sold over two million copies and prompted profound shifts in how many readers relate to their own minds." },
  { title: "Dare to Lead", author: "Brene Brown", genre: "Self-Help", mood: "Motivational", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780399592522-L.jpg", description: "Brave work, tough conversations, whole hearts — a guide to daring leadership.", summary: "Based on eight years of research into courageous leadership, Brown argues that the future of leadership is not armoured, rank-driven, or emotionally closed — it is empathetic, clear, and willing to be vulnerable. She introduces concepts like rumbling with vulnerability, living into values, and learning to rise after failure. Unlike many leadership books, Dare to Lead is as interested in emotional intelligence as in strategy, and its practical tools — particularly around difficult conversations and feedback — are genuinely useful for anyone who leads teams or navigates complex organisations." },
  { title: "Can't Hurt Me", author: "David Goggins", genre: "Self-Help", mood: "Motivational", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9781544512280-L.jpg", description: "From abusive childhood to Navy SEAL — Goggins shows us how to unlock our true potential.", summary: "David Goggins grew up in a household defined by poverty and abuse, was nearly illiterate as a young adult, and weighed 300 pounds when he decided to become a Navy SEAL. His memoir is one of the most extreme accounts of self-transformation ever written, documenting the physical and psychological methods he used to push through limits that most people would consider absolute. Goggins' concept of the 40% rule — the idea that when you feel you've hit your limit, you're actually only at 40% of your capacity — has resonated with millions. Brutal, motivating, and impossible to dismiss." },

  // SCIENCE FICTION
  { title: "Dune", author: "Frank Herbert", genre: "Science Fiction", mood: "Adventure", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780441013593-L.jpg", description: "A young nobleman navigates treachery, religion, and destiny on a desert planet with a world-altering resource.", summary: "On the desert planet Arrakis — the only source of the spice melange, the most valuable substance in the universe — the young Paul Atreides arrives with his family to govern, only to be caught in a betrayal that destroys everything he knows. Herbert's 1965 masterpiece is one of the most complex and carefully constructed science fiction novels ever written, exploring politics, religion, ecology, and the dangers of messianic thinking. The world of Dune, with its Fremen culture, sandworms, and intricate power struggles, is as rich as any in literary fiction. An indispensable achievement." },
  { title: "Project Hail Mary", author: "Andy Weir", genre: "Science Fiction", mood: "Adventure", rating: 4.9, image: "https://covers.openlibrary.org/b/isbn/9780593135204-L.jpg", description: "A lone astronaut must save Earth from disaster — and he cannot even remember his own name.", summary: "Ryland Grace wakes up alone on a spacecraft with no memory of who he is or how he got there. Piece by piece, his past comes back to him: Earth is dying, its sun is being dimmed by an alien microorganism, and he is the last hope of humanity on a one-way mission to find a solution. Weir's scientific problem-solving ingenuity is on full display, and he adds something new here: one of the most joyful, genuinely moving friendships in science fiction history, between Ryland and an alien called Rocky. Hilarious, brilliant, and unexpectedly emotional — widely considered Weir's best work." },
  { title: "1984", author: "George Orwell", genre: "Science Fiction", mood: "Thought-Provoking", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780451524935-L.jpg", description: "A terrifying portrait of a totalitarian future where Big Brother watches every move.", summary: "In Airstrip One — formerly Britain — Winston Smith works at the Ministry of Truth, rewriting historical records to match the Party's current narrative. He secretly yearns for rebellion, begins a forbidden love affair with Julia, and makes contact with what he believes is an underground resistance. Orwell's novel, published in 1949, invented much of the language now used to describe authoritarian surveillance: Big Brother, doublethink, Room 101, the Memory Hole. More than a Cold War allegory, 1984 is a profoundly psychological novel about how power operates through language and how it destroys the capacity for independent thought." },
  { title: "The Hitchhiker's Guide to the Galaxy", author: "Douglas Adams", genre: "Science Fiction", mood: "Funny", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780345391803-L.jpg", description: "The Earth is demolished for a hyperspace bypass. Arthur Dent hitches a ride across the galaxy.", summary: "On an ordinary Thursday morning, Arthur Dent's house is demolished to make way for a bypass. Minutes later, Earth is demolished for the same reason — to make way for a hyperspace bypass. Arthur is saved by his friend Ford Prefect, who turns out to be a researcher for the Hitchhiker's Guide to the Galaxy, a device that is more useful than the Encyclopedia Galactica because it is cheaper and has the words 'Don't Panic' printed on the cover. Adams' novel is a comedy of cosmic proportions, endlessly quotable, and a genuine argument — delivered through absurdism — that the universe is stranger and funnier than any of us have imagined." },
  { title: "Ender's Game", author: "Orson Scott Card", genre: "Science Fiction", mood: "Adventure", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780812550702-L.jpg", description: "A gifted child is recruited to save humanity from an alien invasion through war games.", summary: "Six-year-old Andrew (Ender) Wiggin, identified by the military as the genius needed to lead humanity's defence against the alien Formics, is taken to Battle School where children are trained through increasingly complex war games. Card's novel works as a gripping military adventure, a sharp critique of how institutions use and discard gifted children, and a meditation on the moral weight of actions taken without full understanding. The final chapter's revelation reframes everything that preceded it with devastating effect. One of the most influential science fiction novels of the twentieth century." },
  { title: "The Martian", author: "Andy Weir", genre: "Science Fiction", mood: "Funny", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780553418026-L.jpg", description: "An astronaut is stranded on Mars and must use science and humor to survive until rescue arrives.", summary: "When a freak accident forces his crew to leave without him, astronaut and botanist Mark Watney finds himself alone on Mars, with supplies for 31 days and a rescue that — if it's coming at all — is years away. Weir's novel is a triumph of problem-solving entertainment: Watney's log entries are funny, inventive, and scientifically rigorous, as he figures out how to grow food on a planet without water, communicate with Earth, and survive one catastrophe after another. The Martian makes science feel exciting and human resilience feel genuinely inspiring." },
  { title: "Brave New World", author: "Aldous Huxley", genre: "Science Fiction", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780060850524-L.jpg", description: "In a future of stability and pleasure, one man questions the cost of a controlled society.", summary: "In the World State of 2540, humanity has achieved stability through genetic engineering, psychological conditioning, and the universal use of a happiness-inducing drug called soma. Citizens are happy — relentlessly, shallowly happy. Bernard Marx, an Alpha-Plus psychologist with an unusual degree of self-awareness, begins to question whether a life of engineered contentment is truly living. Huxley's dystopia is often compared to 1984 but cuts differently: where Orwell feared pain and fear as control mechanisms, Huxley feared pleasure and comfort. Both, it turns out, were prescient." },
  { title: "Fahrenheit 451", author: "Ray Bradbury", genre: "Science Fiction", mood: "Thought-Provoking", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9781451673319-L.jpg", description: "A fireman in a dystopian future burns books — until he begins to question everything.", summary: "Guy Montag is a fireman in a future America where firemen don't extinguish fires — they start them, burning books that have been outlawed for the discontent they cause. After a series of encounters — with a young woman who asks questions no one else asks, with a professor who remembers how the world was — Montag begins to read the books he's supposed to burn, and his world unravels. Bradbury's novel is a passionate defence of literature, intellectual freedom, and the life of the mind — written with a poet's eye for image and a moralist's sense of urgency." },
  { title: "The Left Hand of Darkness", author: "Ursula K. Le Guin", genre: "Science Fiction", mood: "Thought-Provoking", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780441478125-L.jpg", description: "An envoy to a planet with genderless inhabitants explores politics, loyalty, and identity.", summary: "Genly Ai is sent to the planet Gethen as an envoy from an interplanetary confederation, tasked with persuading its nations to join. Gethenians are ambisexual — they have no fixed gender — and Genly struggles to understand a culture built on entirely different assumptions about identity. His eventual friendship with the exiled politician Estraven, and their desperate crossing of an ice shelf, forms one of science fiction's most profound explorations of trust, difference, and what we mean by humanity. Le Guin's prose is beautiful and her thinking is decades ahead of its time." },
  { title: "Snow Crash", author: "Neal Stephenson", genre: "Science Fiction", mood: "Adventure", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780553380958-L.jpg", description: "A hacker fights a linguistic virus in a hyperreal virtual reality America.", summary: "In a near-future America balkanised into corporate franchise states, Hiro Protagonist is a pizza delivery driver and part-time hacker who discovers a new drug called Snow Crash that is somehow both a physical narcotic and a computer virus infecting the Metaverse — the virtual reality internet. Stephenson's 1992 novel coined the term 'metaverse,' predicted online virtual worlds, and wrapped it all in a breathtaking thriller involving Sumerian linguistics, ancient viruses, and a media mogul with dangerous ambitions. Wild, funny, and prophetic, it remains the essential cyberpunk novel of its era." },

  // HISTORICAL
  { title: "Educated", author: "Tara Westover", genre: "Historical", mood: "Inspiring", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780399590504-L.jpg", description: "A woman kept out of school escapes her survivalist family and earns a PhD from Cambridge.", summary: "Tara Westover grew up in a survivalist family in rural Idaho with no birth certificate, no medical care, and no formal schooling. Her father believed the end of days was imminent; her family avoided the government in every way they could. Westover taught herself enough to pass a college entrance exam, eventually earning a doctorate from Cambridge. Her memoir is an extraordinary account of self-invention — the daughter of people who believe education is a form of brainwashing, learning to think for herself. Raw, precise, and deeply unsettling in its portrait of a charismatic but dangerous family system." },
  { title: "The Seven Husbands of Evelyn Hugo", author: "Taylor Jenkins Reid", genre: "Historical", mood: "Romantic", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9781501161933-L.jpg", description: "An aging Hollywood icon reveals her scandalous life to a nobody reporter — a secret connects them.", summary: "Reclusive Hollywood legend Evelyn Hugo, now in her late seventies, chooses an unknown magazine journalist named Monique Grant to write her biography — and Monique has no idea why. As Evelyn recounts the story of her seven marriages across the decades of Old Hollywood, she reveals the truth behind the glamour: the strategic unions, the genuine loves, the secrets kept for half a century, and the one great love of her life she could never fully claim. Reid's novel is propulsive and emotionally rich, a love letter to Golden Age Hollywood and a searingly honest story about ambition, identity, and survival." },
  { title: "All the Light We Cannot See", author: "Anthony Doerr", genre: "Historical", mood: "Emotional", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9781476746586-L.jpg", description: "A blind French girl and a German boy cross paths in occupied France during World War II.", summary: "Marie-Laure, a blind French girl, is raised by her locksmith father in Paris, where he builds her tiny wooden models of their neighbourhood so she can navigate it by touch. Werner Pfennig is an orphan boy in Germany gifted with electronics, whose talent propels him into the Hitler Youth and toward the Western Front. Doerr's Pulitzer Prize-winning novel interweaves their stories across the years of the war, converging in the besieged city of Saint-Malo. His prose is luminous and his moral vision deeply humane — a novel about the beauty that persists even at the edges of catastrophe." },
  { title: "The Pillars of the Earth", author: "Ken Follett", genre: "Historical", mood: "Adventure", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780451166890-L.jpg", description: "An epic tale of the building of a cathedral in medieval England and the lives it shapes.", summary: "Set in twelfth-century England during a period of civil war, The Pillars of the Earth follows the decades-long effort to build a magnificent cathedral in the fictional town of Kingsbridge. Around this project, Follett weaves the intertwined lives of a master builder, a prior, a noble woman, a knight, and an outlaw — their alliances, betrayals, loves, and enmities played out against the backdrop of royal succession, church politics, and the mechanics of medieval construction. Follett's research is meticulous and his storytelling instinct is superb. An epic in the truest sense: vast, absorbing, and deeply human." },
  { title: "Wolf Hall", author: "Hilary Mantel", genre: "Historical", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780312429980-L.jpg", description: "Thomas Cromwell rises to power in the court of Henry VIII through cunning and quiet genius.", summary: "Thomas Cromwell, the son of a Putney blacksmith, rises to become Henry VIII's chief minister through a combination of intelligence, discretion, and an exceptional ability to understand what people want. Mantel's Booker Prize-winning novel tells his story through an unusual second-person perspective that makes Cromwell the gravitational centre of every scene, while the King, Anne Boleyn, and Cardinal Wolsey orbit around him. Dense and demanding, it rewards immensely — Mantel's historical imagination is unmatched, and her Cromwell is one of the most compelling figures in modern fiction." },
  { title: "The Name of the Rose", author: "Umberto Eco", genre: "Historical", mood: "Suspenseful", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780151446476-L.jpg", description: "A medieval monk investigates a series of mysterious deaths in an Italian abbey.", summary: "In 1327, Franciscan friar William of Baskerville and his novice Adso arrive at a prosperous Italian Benedictine abbey to attend a theological disputation — and find themselves investigating a series of mysterious deaths connected to the abbey's labyrinthine library. Eco's debut novel is simultaneously a brilliant mystery, a philosophical treatise on the nature of knowledge and signs, and a richly detailed portrait of medieval intellectual life. The detective plot is propulsive, the historical detail astonishing, and the climax — involving a forbidden book and a library on fire — is one of the great endings in twentieth-century literature." },
  { title: "Pachinko", author: "Min Jin Lee", genre: "Historical", mood: "Emotional", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9781455563920-L.jpg", description: "Four generations of a Korean family navigate identity, sacrifice, and survival in Japan." },
  { title: "The Nightingale", author: "Kristin Hannah", genre: "Historical", mood: "Emotional", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780312577223-L.jpg", description: "Two sisters in WWII France choose different paths of survival, resistance, and love." },
  { title: "Sapiens", author: "Yuval Noah Harari", genre: "Historical", mood: "Thought-Provoking", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780062316097-L.jpg", description: "A brief history of humankind from the first humans to the present, told with bold ideas." },
  { title: "The Diary of a Young Girl", author: "Anne Frank", genre: "Historical", mood: "Emotional", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780553296983-L.jpg", description: "The real diary kept by a Jewish teenager hiding in Amsterdam during the Nazi occupation." },

  // MYSTERY
  { title: "The Shadow of the Wind", author: "Carlos Ruiz Zafon", genre: "Mystery", mood: "Dark", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780143034902-L.jpg", description: "A young boy discovers a mysterious book and is drawn into a labyrinth of Barcelona's dark history." },
  { title: "Where the Crawdads Sing", author: "Delia Owens", genre: "Mystery", mood: "Emotional", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780735224292-L.jpg", description: "A girl raised alone in the marshes becomes a murder suspect in a lyrical coming-of-age mystery." },
  { title: "And Then There Were None", author: "Agatha Christie", genre: "Mystery", mood: "Suspenseful", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780312330873-L.jpg", description: "Ten strangers are lured to an island and one by one, they begin to die." },
  { title: "The Hound of the Baskervilles", author: "Arthur Conan Doyle", genre: "Mystery", mood: "Suspenseful", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780192835895-L.jpg", description: "Sherlock Holmes investigates a supernatural hound terrorising a noble family on the moors." },
  { title: "The Thursday Murder Club", author: "Richard Osman", genre: "Mystery", mood: "Funny", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781984880963-L.jpg", description: "Four elderly friends in a retirement village solve cold cases until a real murder arrives." },
  { title: "Rebecca", author: "Daphne du Maurier", genre: "Mystery", mood: "Dark", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780380730407-L.jpg", description: "A young bride finds herself haunted by the memory of her husband's first wife, Rebecca." },
  { title: "The Girl on the Train", author: "Paula Hawkins", genre: "Mystery", mood: "Suspenseful", rating: 3.9, image: "https://covers.openlibrary.org/b/isbn/9781594634024-L.jpg", description: "A woman obsessed with a couple she watches from a train gets pulled into a murder investigation." },
  { title: "The No. 1 Ladies Detective Agency", author: "Alexander McCall Smith", genre: "Mystery", mood: "Happy", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781400034772-L.jpg", description: "Botswana's first female detective uses wisdom and warmth to solve colourful local mysteries." },
  { title: "Murder on the Orient Express", author: "Agatha Christie", genre: "Mystery", mood: "Suspenseful", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780062693662-L.jpg", description: "Hercule Poirot investigates a murder on a snowbound luxury train — every passenger is a suspect." },
  { title: "The Cuckoo's Calling", author: "Robert Galbraith", genre: "Mystery", mood: "Dark", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780316206860-L.jpg", description: "Private detective Cormoran Strike investigates the apparent suicide of a supermodel." },

  // BIOGRAPHY
  { title: "Steve Jobs", author: "Walter Isaacson", genre: "Biography", mood: "Inspiring", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781451648539-L.jpg", description: "The definitive biography of Apple's visionary co-founder, based on 40 exclusive interviews." },
  { title: "Becoming", author: "Michelle Obama", genre: "Biography", mood: "Inspiring", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9781524763138-L.jpg", description: "The former First Lady shares her journey from Chicago's South Side to the White House." },
  { title: "Long Walk to Freedom", author: "Nelson Mandela", genre: "Biography", mood: "Inspiring", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780316548182-L.jpg", description: "Mandela's autobiography chronicling his struggle to end apartheid and become South Africa's president." },
  { title: "I Know Why the Caged Bird Sings", author: "Maya Angelou", genre: "Biography", mood: "Inspiring", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780345514400-L.jpg", description: "Maya Angelou's story of trauma, resilience, and identity growing up Black in America." },
  { title: "Born a Crime", author: "Trevor Noah", genre: "Biography", mood: "Funny", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780399588174-L.jpg", description: "A comedian's hilarious and moving memoir about growing up mixed-race in apartheid South Africa." },
  { title: "The Glass Castle", author: "Jeannette Walls", genre: "Biography", mood: "Emotional", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780743247542-L.jpg", description: "A remarkable memoir about a chaotic childhood with unconventional, nomadic parents." },
  { title: "The Autobiography of Malcolm X", author: "Malcolm X", genre: "Biography", mood: "Inspiring", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780345350688-L.jpg", description: "The powerful story of one of the 20th century's most controversial and influential figures." },
  { title: "Open", author: "Andre Agassi", genre: "Biography", mood: "Inspiring", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780307388407-L.jpg", description: "Tennis legend Andre Agassi's brutally honest memoir about success, rebellion, and redemption." },
  { title: "When Breath Becomes Air", author: "Paul Kalanithi", genre: "Biography", mood: "Emotional", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780812988406-L.jpg", description: "A neurosurgeon facing terminal cancer reflects on what makes a life worth living." },
  { title: "Shoe Dog", author: "Phil Knight", genre: "Biography", mood: "Inspiring", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9781501135910-L.jpg", description: "Nike's founder tells the story of building one of the world's most recognisable brands from scratch." },

  // HORROR
  { title: "The Shining", author: "Stephen King", genre: "Horror", mood: "Dark", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780307743657-L.jpg", description: "A family caretaking a remote hotel over winter as supernatural forces unleash the father's darkness." },
  { title: "It", author: "Stephen King", genre: "Horror", mood: "Dark", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9781501142970-L.jpg", description: "Seven kids face their deepest fears and a creature that calls itself Pennywise the Dancing Clown." },
  { title: "Dracula", author: "Bram Stoker", genre: "Horror", mood: "Dark", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780141439846-L.jpg", description: "Count Dracula ventures from Transylvania to England, and a group of heroes unite to stop him." },
  { title: "Frankenstein", author: "Mary Shelley", genre: "Horror", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780141439471-L.jpg", description: "Victor Frankenstein creates a living being from dead matter and faces the consequences of playing God." },
  { title: "The Haunting of Hill House", author: "Shirley Jackson", genre: "Horror", mood: "Dark", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780143039983-L.jpg", description: "Four people summoned to a notoriously haunted mansion — and the house is waiting for them." },

  // MYSTERY (remaining)
  { title: "Pachinko", author: "Min Jin Lee", genre: "Historical", mood: "Emotional", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9781455563920-L.jpg", description: "Four generations of a Korean family navigate identity, sacrifice, and survival in Japan.", summary: "Beginning in a Korean fishing village in 1910 and spanning four generations to 1989 Osaka, Pachinko follows the descendants of Sunja, a young woman who makes a fateful choice that will define her family for decades. Her children and grandchildren navigate life as ethnic Koreans in Japan — a community that faces profound discrimination and is neither fully Korean nor accepted as Japanese. Min Jin Lee's epic is a novel about identity, sacrifice, and the weight of history on individual lives. Its prose is quiet and devastating, its characters unforgettable, and its scope genuinely vast." },
  { title: "The Nightingale", author: "Kristin Hannah", genre: "Historical", mood: "Emotional", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780312577223-L.jpg", description: "Two sisters in WWII France choose different paths of survival, resistance, and love.", summary: "In German-occupied France, two sisters respond to war in radically different ways. Vianne, older and pragmatic, focuses on keeping her daughter safe; Isabelle, young and fearless, joins the French Resistance and begins leading shot-down Allied airmen across the Pyrenees to Spain. Hannah weaves their stories across the years of occupation and liberation, building toward a revelation that reframes the entire novel. A bestseller for its emotional power and meticulous historical research, The Nightingale is one of the most celebrated WWII novels of recent years." },
  { title: "Sapiens", author: "Yuval Noah Harari", genre: "Historical", mood: "Thought-Provoking", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780062316097-L.jpg", description: "A brief history of humankind from the first humans to the present, told with bold ideas.", summary: "Harari's sweeping history of humanity argues that what distinguishes Homo sapiens from other animals is our unique ability to believe in shared fictions — nations, religions, money, corporations. This cognitive revolution enabled mass cooperation and made us the dominant species on Earth. Written with enormous clarity and audacious synthesis, Sapiens moves from prehistoric migration patterns to the Agricultural Revolution to the rise of capitalism and empire, consistently asking not just what happened but what it meant for human happiness. One of the most widely read and debated works of popular history in the twenty-first century." },
  { title: "The Diary of a Young Girl", author: "Anne Frank", genre: "Historical", mood: "Emotional", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780553296983-L.jpg", description: "The real diary kept by a Jewish teenager hiding in Amsterdam during the Nazi occupation.", summary: "Between 1942 and 1944, thirteen-year-old Anne Frank kept a diary while hiding with her family in a secret annex above her father's Amsterdam offices. Her writing — intelligent, funny, self-aware, and deeply human — documents two years of concealment, fear, and the determination to maintain hope in impossible circumstances. Anne was discovered in August 1944 and died in Bergen-Belsen concentration camp eight months later. Her father, the only member of their group to survive, found her diary and published it. It has since been translated into 70 languages and read by tens of millions of people worldwide." },

  // MYSTERY
  { title: "The Shadow of the Wind", author: "Carlos Ruiz Zafon", genre: "Mystery", mood: "Dark", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780143034902-L.jpg", description: "A young boy discovers a mysterious book and is drawn into a labyrinth of Barcelona's dark history.", summary: "In post-war Barcelona, ten-year-old Daniel is taken by his bookseller father to the Cemetery of Forgotten Books — a secret library where every visitor must choose one book to preserve. Daniel chooses a novel called The Shadow of the Wind by Julian Carax. As he seeks to learn more about the obscure author, he discovers that someone has been systematically destroying every copy of Carax's books — and that the mystery connects to dark events during the Spanish Civil War. Zafón's Gothic romance is a love letter to books, Barcelona, and literary mystery — atmospheric, romantic, and beautifully crafted." },
  { title: "Where the Crawdads Sing", author: "Delia Owens", genre: "Mystery", mood: "Emotional", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780735224292-L.jpg", description: "A girl raised alone in the marshes becomes a murder suspect in a lyrical coming-of-age mystery.", summary: "Kya Clark, known as the Marsh Girl, has raised herself alone in the North Carolina marshes after being abandoned by her family. Self-educated, deeply knowledgeable about the natural world, and profoundly lonely, she forms two significant connections with young men from town — and when one of them is found dead, she becomes the prime suspect. Owens alternates between Kya's coming-of-age narrative and the murder investigation, building to a genuinely surprising resolution. Lyrical, emotional, and grounded in exceptional nature writing, it became one of the most widely read novels of its decade." },
  { title: "And Then There Were None", author: "Agatha Christie", genre: "Mystery", mood: "Suspenseful", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780312330873-L.jpg", description: "Ten strangers are lured to an island and one by one, they begin to die.", summary: "Ten strangers, each with a guilty secret, are lured to an isolated island off the Devon coast by a mysterious host who never appears. As a recorded voice accuses each of them of murder, and as the guests begin dying one by one in accordance with a nursery rhyme, the survivors must find the killer among themselves. Christie's most ingeniously constructed puzzle — the bestselling mystery novel of all time — presents an impossible problem and solves it with breathtaking fairness. The solution remains one of the most startling and satisfying in the genre's history." },
  { title: "The Hound of the Baskervilles", author: "Arthur Conan Doyle", genre: "Mystery", mood: "Suspenseful", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780192835895-L.jpg", description: "Sherlock Holmes investigates a supernatural hound terrorising a noble family on the moors.", summary: "The Baskerville family has been cursed, according to legend, by a demonic hound since the seventeenth century. When Sir Charles Baskerville is found dead on the moor with an expression of terror on his face and giant footprints nearby, Sherlock Holmes and Dr. Watson are called in to protect the new heir. Conan Doyle's most celebrated novel is a masterpiece of Gothic atmosphere, combining the foggy, treacherous Dartmoor setting with his detective's relentless rationalism. The balance between supernatural menace and logical explanation has never been handled better in the genre." },
  { title: "The Thursday Murder Club", author: "Richard Osman", genre: "Mystery", mood: "Funny", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781984880963-L.jpg", description: "Four elderly friends in a retirement village solve cold cases until a real murder arrives.", summary: "In a luxury retirement village in the Kent countryside, four residents — Elizabeth, Joyce, Ibrahim, and Ron — meet weekly to examine unsolved murders. When a real-life killing occurs on their doorstep, they find themselves in the middle of an actual investigation. Osman's novel is warm, witty, and deeply affectionate toward its elderly protagonists, who are sharp, funny, and utterly unintimidated by anyone. Part cosy mystery, part comedy of manners, and part surprisingly moving meditation on ageing and friendship, it launched one of the most successful British mystery series of recent years." },
  { title: "Rebecca", author: "Daphne du Maurier", genre: "Mystery", mood: "Dark", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780380730407-L.jpg", description: "A young bride finds herself haunted by the memory of her husband's first wife, Rebecca.", summary: "A young, unnamed woman marries the wealthy widower Maxim de Winter and moves into his magnificent estate, Manderley. But the house is saturated with the memory of Rebecca, Maxim's first wife — maintained obsessively by the sinister housekeeper Mrs. Danvers, whispered about by every servant. Du Maurier's Gothic masterpiece operates on multiple levels simultaneously: as a psychological study of insecurity and jealousy, as a mystery about what really happened to Rebecca, and as a meditation on the power of the dead over the living. Its opening sentence — 'Last night I dreamt I went to Manderley again' — is among the most famous in English literature." },
  { title: "The Girl on the Train", author: "Paula Hawkins", genre: "Mystery", mood: "Suspenseful", rating: 3.9, image: "https://covers.openlibrary.org/b/isbn/9781594634024-L.jpg", description: "A woman obsessed with a couple she watches from a train gets pulled into a murder investigation.", summary: "Rachel Watson takes the same commuter train every day, passing the same row of houses, watching the same couple on their terrace — two people she has decided are perfect. When the woman goes missing and Rachel's blackout-prone memory makes her an unreliable witness to something she may have seen, she becomes entangled in the investigation. Hawkins tells her story through multiple unreliable narrators, each withholding information and misremembering events. A propulsive, atmospheric domestic thriller with a genuine surprise ending that keeps you reading through the night." },
  { title: "The No. 1 Ladies Detective Agency", author: "Alexander McCall Smith", genre: "Mystery", mood: "Happy", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781400034772-L.jpg", description: "Botswana's first female detective uses wisdom and warmth to solve colourful local mysteries.", summary: "Precious Ramotswe uses her father's legacy — a small herd of cattle — to establish Botswana's first and only female-run detective agency. Her cases are gentle, human-scaled, and often less about crime than about lost people, difficult relationships, and local disputes. McCall Smith's series is unlike any other mystery fiction: warm, leisurely, and deeply affectionate toward both its heroine and the country of Botswana. Mma Ramotswe solves her cases not through deduction but through patience, empathy, and her formidable understanding of human nature. A balm for anyone who finds other mysteries too dark." },
  { title: "Murder on the Orient Express", author: "Agatha Christie", genre: "Mystery", mood: "Suspenseful", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780062693662-L.jpg", description: "Hercule Poirot investigates a murder on a snowbound luxury train — every passenger is a suspect.", summary: "Hercule Poirot, returning from a case in Syria, boards the famous Orient Express — and finds himself stranded in Yugoslavia when snow blocks the tracks. During the night, one of the passengers is found stabbed to death, and Poirot must investigate before any outside authority can arrive. All twelve remaining passengers are suspects; all have alibis; all are hiding something. Christie's most celebrated Poirot novel delivers one of the most ingenious solutions in mystery fiction history — a solution that feels both completely fair and utterly surprising, and which raises profound questions about justice." },
  { title: "The Cuckoo's Calling", author: "Robert Galbraith", genre: "Mystery", mood: "Dark", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780316206860-L.jpg", description: "Private detective Cormoran Strike investigates the apparent suicide of a supermodel.", summary: "When supermodel Lula Landry apparently jumps from her London balcony in January, the verdict is suicide. But her brother refuses to believe it, and hires limping, down-on-his-luck private detective Cormoran Strike to look again. What Strike uncovers is a world of fashion, celebrity, inherited wealth, and carefully maintained lies. Published under the pseudonym Robert Galbraith (later revealed as J.K. Rowling), The Cuckoo's Calling is a confidently plotted, character-rich detective novel that launched one of contemporary crime fiction's most popular series. Strike himself — damaged, brilliant, and stubbornly decent — is an original creation." },

  // BIOGRAPHY
  { title: "Steve Jobs", author: "Walter Isaacson", genre: "Biography", mood: "Inspiring", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9781451648539-L.jpg", description: "The definitive biography of Apple's visionary co-founder, based on 40 exclusive interviews.", summary: "Based on more than forty interviews with Jobs himself, as well as conversations with over a hundred family members, friends, adversaries, competitors, and colleagues, Isaacson's biography reveals an extraordinary figure: a visionary who could inspire extraordinary loyalty and creativity in others while also being capable of profound cruelty, dishonesty, and manipulation. The book traces his Silicon Valley origins through the founding of Apple, his exile, his return and the creation of the iMac, iPod, iPhone, and iPad. Isaacson doesn't flinch from the darker aspects of Jobs's personality, making this one of the most honest portraits of a tech genius ever published." },
  { title: "Becoming", author: "Michelle Obama", genre: "Biography", mood: "Inspiring", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9781524763138-L.jpg", description: "The former First Lady shares her journey from Chicago's South Side to the White House.", summary: "Michelle Obama's memoir traces her journey from a working-class family on Chicago's South Side, through Princeton and Harvard Law School, to her career as a hospital executive, and finally to eight years in the White House as America's First Lady. Obama writes with unusual candour about race, gender, ambition, marriage, and the particular challenges of being a Black woman in American public life. Her account of the First Lady years is honest about the constraints of the role and the toll of constant scrutiny. Warmly written, thoughtful, and deeply personal, it became the bestselling memoir of all time." },
  { title: "Long Walk to Freedom", author: "Nelson Mandela", genre: "Biography", mood: "Inspiring", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780316548182-L.jpg", description: "Mandela's autobiography chronicling his struggle to end apartheid and become South Africa's president.", summary: "Written largely in secret during his twenty-seven years of imprisonment on Robben Island, Mandela's autobiography traces his childhood in the Transkei, his political awakening in Johannesburg, his founding role in the African National Congress Youth League, and his decision that nonviolent resistance was insufficient to combat apartheid. His account of prison life — the hard labour, the meagre food, the small acts of dignity and resistance — is among the most moving in modern memoir. The book ends with the elections of 1994 and stands as testimony to the extraordinary capacity of a human being for patience, forgiveness, and moral growth." },
  { title: "I Know Why the Caged Bird Sings", author: "Maya Angelou", genre: "Biography", mood: "Inspiring", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780345514400-L.jpg", description: "Maya Angelou's story of trauma, resilience, and identity growing up Black in America.", summary: "The first of Angelou's seven autobiographies covers her childhood and early adolescence in the Depression-era American South — growing up with her grandmother in Stamps, Arkansas; experiencing sexual assault at eight; the years of selective mutism that followed; and her gradual recovery through literature and the support of a remarkable teacher. Angelou's prose is lyrical and precise, her perspective both child-like in its immediacy and adult in its understanding. A landmark of African American literature and one of the most celebrated memoirs in American literary history, it made Angelou's name and changed how autobiography was understood." },
  { title: "Born a Crime", author: "Trevor Noah", genre: "Biography", mood: "Funny", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780399588174-L.jpg", description: "A comedian's hilarious and moving memoir about growing up mixed-race in apartheid South Africa.", summary: "Trevor Noah was born to a Swiss father and a Xhosa mother in South Africa in 1984 — at a time when such a relationship was literally illegal under apartheid law. His very existence was a crime. Noah's memoir recounts his chaotic, funny, and often dangerous childhood: hiding from police, navigating gang territories, learning to speak multiple languages as a form of social camouflage, and developing the observational humour that would eventually take him to The Daily Show. Equal parts comedy and political education, Born a Crime is one of the funniest and most illuminating accounts of life under apartheid ever written." },
  { title: "The Glass Castle", author: "Jeannette Walls", genre: "Biography", mood: "Emotional", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780743247542-L.jpg", description: "A remarkable memoir about a chaotic childhood with unconventional, nomadic parents.", summary: "Jeannette Walls grew up in a family that moved constantly — fleeing creditors, abandoning burning houses, living in desert shacks and Appalachian poverty — with parents who were brilliant, irresponsible, and utterly committed to their own unconventional vision of life. Her father, a genius alcoholic, promised to build the family a dream house called the Glass Castle; it was never built. Walls writes about her childhood with clarity, compassion, and an absence of self-pity that makes the memoir more devastating, not less. One of the most widely read memoirs of the twenty-first century." },
  { title: "The Autobiography of Malcolm X", author: "Malcolm X", genre: "Biography", mood: "Inspiring", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780345350688-L.jpg", description: "The powerful story of one of the 20th century's most controversial and influential figures.", summary: "Told to Alex Haley over three years before Malcolm X's assassination in 1965, this autobiography traces his journey from a childhood marked by white supremacist violence and his father's death, through a teenage life of crime and prison, to his conversion to Islam and transformation into one of the most powerful Black voices in America, and finally his break with the Nation of Islam and evolution toward a more universal humanism. Searing, urgent, and deeply honest about his own changes of mind, it remains one of the essential texts of American political history and a masterpiece of the autobiography form." },
  { title: "Open", author: "Andre Agassi", genre: "Biography", mood: "Inspiring", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780307388407-L.jpg", description: "Tennis legend Andre Agassi's brutally honest memoir about success, rebellion, and redemption.", summary: "Andre Agassi's memoir is startling in its honesty: he reveals that he hated tennis for much of his career, that his famous hair was a wig, that he used crystal meth in 1997, and that the sport he came to love was one he had to choose freely to really embrace. Written with sportswriter J.R. Moehringer, Open charts Agassi's childhood under a domineering father, his rise to the top, his fall from it, and his remarkable late-career return to the number one ranking. More than a sports memoir, it is a story about finding meaning in work you didn't choose and learning to become yourself." },
  { title: "When Breath Becomes Air", author: "Paul Kalanithi", genre: "Biography", mood: "Emotional", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780812988406-L.jpg", description: "A neurosurgeon facing terminal cancer reflects on what makes a life worth living.", summary: "Paul Kalanithi was thirty-six, in the final year of his neurosurgery residency, when he was diagnosed with Stage IV lung cancer. His memoir, written in the months before his death in 2015, is a meditation on what makes life meaningful — questions he had pursued through literature before medical school and then through the intimacy of neurosurgery, where the boundary between life and death is managed millimetre by millimetre. Kalanithi writes with both scientific precision and genuine literary beauty. The result is one of the most profound and moving books about mortality in recent memory." },
  { title: "Shoe Dog", author: "Phil Knight", genre: "Biography", mood: "Inspiring", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9781501135910-L.jpg", description: "Nike's founder tells the story of building one of the world's most recognisable brands from scratch.", summary: "In 1962, Phil Knight borrowed fifty dollars from his father and set off on a trip around the world, eventually arriving in Japan where he convinced a shoe manufacturer to let him sell their shoes in America. That modest beginning eventually became Nike. Knight's memoir covers the years from that first trip to Nike's IPO in 1980, recounting the company's perpetual near-death experiences with banks, suppliers, and the IRS, the relationships with early employees who became legends, and his own complicated relationship with ambition and success. Remarkably candid, compulsively readable, and genuinely useful to anyone who has ever tried to build something from nothing." },

  // HORROR
  { title: "The Shining", author: "Stephen King", genre: "Horror", mood: "Dark", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9780307743657-L.jpg", description: "A family caretaking a remote hotel over winter as supernatural forces unleash the father's darkness.", summary: "Jack Torrance, a recovering alcoholic and struggling writer, takes a winter caretaking job at the remote Overlook Hotel in Colorado, bringing his wife Wendy and their young son Danny — a boy with the psychic ability his mentor calls 'shining.' As the winter isolation deepens and the hotel's dark history begins to assert itself, Jack's tenuous sobriety and sanity erode. King's novel is simultaneously a ghost story, a study of alcoholism and domestic violence, and a meditation on the sins parents visit on their children. The Overlook Hotel, with its topiary animals and blood-seeping elevators, is one of the great settings in horror fiction." },
  { title: "It", author: "Stephen King", genre: "Horror", mood: "Dark", rating: 4.6, image: "https://covers.openlibrary.org/b/isbn/9781501142970-L.jpg", description: "Seven kids face their deepest fears and a creature that calls itself Pennywise the Dancing Clown.", summary: "In the town of Derry, Maine, children have been disappearing with disturbing regularity for over a century. In 1958, seven misfit children — the self-dubbed Losers Club — discover that an ancient, shape-shifting entity they call It is responsible, and confront it. Decades later, when the killings begin again, they must return. King's longest and arguably most ambitious novel operates on two levels: as a genuinely terrifying horror story and as a rich portrait of childhood, friendship, and the particular terror of powerlessness. Pennywise the Dancing Clown has become one of the most iconic figures in American popular culture." },
  { title: "Dracula", author: "Bram Stoker", genre: "Horror", mood: "Dark", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780141439846-L.jpg", description: "Count Dracula ventures from Transylvania to England, and a group of heroes unite to stop him.", summary: "Told entirely through letters, diary entries, newspaper clippings, and a ship's log, Stoker's epistolary novel follows Jonathan Harker, a young solicitor who travels to Transylvania to assist a Transylvanian nobleman with a London property purchase — and discovers that Count Dracula is not human. As Dracula makes his way to England and begins preying on those Jonathan loves, a group of determined individuals assembles to stop him. Published in 1897, Dracula established almost every vampire convention that has followed. It is also a deeply atmospheric Victorian thriller, its patchwork narrative structure building dread with remarkable efficiency." },
  { title: "Frankenstein", author: "Mary Shelley", genre: "Horror", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780141439471-L.jpg", description: "Victor Frankenstein creates a living being from dead matter and faces the consequences of playing God.", summary: "Victor Frankenstein, a student of natural philosophy, discovers the secret of imparting life to inanimate matter and uses it to create a living being. When the creature he has made proves hideous, Victor abandons him in horror. The creature — intelligent, sensitive, and desperately lonely — turns to violence only after a lifetime of rejection. Shelley's novel, written when she was eighteen, is the founding text of science fiction: a meditation on scientific responsibility, the ethics of creation, and what we owe to the beings we bring into existence. Its questions about ambition, hubris, and the unforeseen consequences of playing God are more urgent now than when it was written." },
  { title: "The Haunting of Hill House", author: "Shirley Jackson", genre: "Horror", mood: "Dark", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780143039983-L.jpg", description: "Four people summoned to a notoriously haunted mansion — and the house is waiting for them.", summary: "Dr. Montague, a paranormal investigator, rents Hill House for the summer and invites three guests: Eleanor, a repressed young woman who has spent years caring for her invalid mother; Theodora, an artistic and confident free spirit; and Luke, the heir to the house. What follows is a masterpiece of psychological horror that never quite commits to whether the haunting is supernatural or a manifestation of Eleanor's fractured psyche. Jackson's prose is extraordinary — her famous opening paragraph, describing the house's architectural wrongness, is widely considered the finest in horror fiction." },

  // PHILOSOPHY
  { title: "Meditations", author: "Marcus Aurelius", genre: "Philosophy", mood: "Thought-Provoking", rating: 4.7, image: "https://covers.openlibrary.org/b/isbn/9780812968255-L.jpg", description: "Personal writings of the Roman Emperor on Stoic philosophy — timeless wisdom for modern life.", summary: "Written in the second century AD, Meditations was never intended for publication. It is a private journal in which the Roman Emperor Marcus Aurelius — one of history's most powerful men — reminded himself daily of Stoic principles: to focus on what is within our control, to treat others with reason and compassion, to accept death without fear, and to serve the common good. Its insights are so practical and so clearly hard-won that they feel contemporary rather than ancient. Beloved by everyone from philosophers to soldiers to entrepreneurs, Meditations is one of the few texts from any era that genuinely improves lives." },
  { title: "The Republic", author: "Plato", genre: "Philosophy", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780872201361-L.jpg", description: "Plato's vision of a just society through dialogue — a cornerstone of Western philosophy.", summary: "In a series of dialogues featuring Socrates, Plato addresses the most fundamental questions of political philosophy: What is justice? What is the ideal state? How should rulers be educated? Who is qualified to govern? The Republic introduces the famous Allegory of the Cave — ordinary humans are like prisoners who can only see shadows on a wall, mistaking them for reality — and the concept of philosopher-kings: those who have ascended to knowledge of the Good and therefore have an obligation to govern justly. Two and a half millennia old, its questions remain the central questions of every society that aspires to be just." },
  { title: "Thus Spoke Zarathustra", author: "Friedrich Nietzsche", genre: "Philosophy", mood: "Thought-Provoking", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780140441185-L.jpg", description: "Zarathustra descends from his mountain cave to share his vision of the Ubermensch with humanity.", summary: "Nietzsche's masterpiece is written in the form of a scripture — deliberately echoing the Bible — but its message is the opposite of religious consolation: God is dead, and humanity must create its own values. Through the prophet Zarathustra, Nietzsche introduces the Übermensch (often poorly translated as 'Superman'), the will to power, and eternal recurrence — the idea that we should live as if we would have to live this exact life over and over forever. Challenging, provocative, and impossible to fully exhaust, it is one of the most influential and most misread books in Western philosophy." },
  { title: "The Art of War", author: "Sun Tzu", genre: "Philosophy", mood: "Motivational", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9781590302255-L.jpg", description: "Ancient Chinese military treatise still applied today in business, leadership, and strategy.", summary: "Written in China approximately 2,500 years ago, Sun Tzu's treatise on military strategy has been studied by generals, politicians, and business leaders across cultures and centuries. Its thirteen chapters — covering topics like strategic planning, the use of intelligence, the management of troops, and the importance of adaptability — compress vast wisdom into memorable aphorisms. The central insight is that the highest form of victory is achieving your objective without direct confrontation. Whether read as military theory, business strategy, or philosophy of conflict and competition, The Art of War rewards close reading in every context." },
  { title: "Sophie's World", author: "Jostein Gaarder", genre: "Philosophy", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780374530716-L.jpg", description: "A young girl receives mysterious letters introducing her to the history of Western philosophy.", summary: "Fourteen-year-old Sophie Amundsen begins receiving mysterious letters asking questions like 'Who are you?' and 'Where does the world come from?' — the beginning of a philosophy correspondence course delivered by a mysterious teacher named Alberto Knox. Through Sophie's education, Gaarder surveys the entire history of Western philosophy from the pre-Socratics to Sartre in an accessible and genuinely engaging narrative. The novel has a meta-fictional dimension that becomes increasingly important as the story develops. One of the bestselling Norwegian novels ever published, it has introduced philosophy to millions of readers who might otherwise never have encountered it." },

  // CLASSIC
  { title: "To Kill a Mockingbird", author: "Harper Lee", genre: "Classic", mood: "Thought-Provoking", rating: 4.8, image: "https://covers.openlibrary.org/b/isbn/9780061935466-L.jpg", description: "Through a child's eyes in Alabama, the story of justice, prejudice, and moral growth.", summary: "Set in the fictional Alabama town of Maycomb during the 1930s, the novel is narrated by six-year-old Scout Finch, whose father Atticus is appointed to defend Tom Robinson — a Black man falsely accused of raping a white woman. Lee's novel operates simultaneously as a coming-of-age story, a courtroom drama, and a searing examination of racial injustice in the American South. Atticus Finch, with his quiet moral courage, became one of literature's great father figures. The Pulitzer Prize-winning novel has been taught in schools worldwide for six decades and remains one of the most widely read American novels ever written." },
  { title: "The Great Gatsby", author: "F. Scott Fitzgerald", genre: "Classic", mood: "Thought-Provoking", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780743273565-L.jpg", description: "The tragedy of the American Dream in the jazz-age world of Long Island's opulent parties.", summary: "Nick Carraway, a Yale graduate from the Midwest, rents a small house on Long Island in the summer of 1922, next door to the mysterious Jay Gatsby — a man famous for his lavish parties and rumoured to have made his fortune in bootlegging. When Nick discovers that Gatsby's obsession is with Nick's cousin Daisy, married to the brutal Tom Buchanan, the stage is set for one of literature's great tragic studies of illusion, reinvention, and the hollow heart of the American Dream. Fitzgerald's prose — dazzling, precise, and melancholic — has never been equalled in its portrait of excess and loss." },
  { title: "Moby-Dick", author: "Herman Melville", genre: "Classic", mood: "Adventure", rating: 4.2, image: "https://covers.openlibrary.org/b/isbn/9780142437247-L.jpg", description: "Captain Ahab's obsessive quest to hunt the legendary white whale across the world's oceans.", summary: "Call me Ishmael. With that opening invitation, Melville begins one of the greatest novels in American literature — the story of the Pequod's voyage under the command of the monomaniacal Captain Ahab, whose sole purpose is vengeance against the white sperm whale that tore away his leg. Moby-Dick is many things simultaneously: a thrilling sea adventure, an exhaustive treatise on the whaling industry, a meditation on obsession and fate, and a profound philosophical inquiry into the nature of evil and the limits of human knowledge. Its difficulty rewards the patient reader with one of the richest experiences in literature." },
  { title: "Crime and Punishment", author: "Fyodor Dostoevsky", genre: "Classic", mood: "Dark", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780143058144-L.jpg", description: "A student commits a murder and is tormented by guilt — a psychological masterpiece.", summary: "Raskolnikov, an impoverished student in Saint Petersburg, murders a pawnbroker whom he considers a parasite on society, convinced that extraordinary people have the right to transgress ordinary moral codes. What follows is a shattering psychological portrait of guilt, paranoia, and the slow crumbling of a man's rationalizations as the investigator Porfiry circles him. Dostoevsky wrote the novel in first-person intimacy with his anti-hero's consciousness, making Crime and Punishment one of the first truly modern psychological novels. Its exploration of nihilism, free will, and redemption remains as urgent as it was in 1866." },
  { title: "Anna Karenina", author: "Leo Tolstoy", genre: "Classic", mood: "Emotional", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780143035008-L.jpg", description: "An aristocratic woman tears apart her life in pursuit of love and freedom in tsarist Russia.", summary: "Anna Karenina, a beautiful and cultivated aristocrat in tsarist Russia, meets the dashing cavalry officer Count Vronsky at a Moscow train station and their mutual attraction sets in motion a tragedy of social exclusion and psychological disintegration. In parallel, Tolstoy traces the contrasting story of Levin — a landowner seeking meaning through work, faith, and marriage — who is widely seen as Tolstoy's self-portrait. The novel is vast and intimate at once, a complete world of high society, country estates, and drawing rooms, animated by Tolstoy's unmatched ability to inhabit consciousness. Often called the greatest novel ever written." },
  { title: "Don Quixote", author: "Miguel de Cervantes", genre: "Classic", mood: "Funny", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780060934347-L.jpg", description: "A man reads so many chivalric romances he loses his mind and sets out to be a knight-errant.", summary: "Alonso Quijano, a middle-aged Spanish gentleman, reads so many chivalric romances that he loses his grip on reality and sets off across La Mancha as the self-appointed knight Don Quixote, accompanied by the peasant Sancho Panza as his squire. Their misadventures — tilting at windmills, mistaking inns for castles — are both comic and poignant, as Cervantes simultaneously parodies the romance genre and creates something more tender and enduring. Published in 1605, Don Quixote is often called the first modern novel: a work that questions the nature of fiction, reality, and the human need to tell stories that make the world more meaningful." },
  { title: "Wuthering Heights", author: "Emily Bronte", genre: "Classic", mood: "Emotional", rating: 4.3, image: "https://covers.openlibrary.org/b/isbn/9780141439556-L.jpg", description: "A tale of passionate love and destructive revenge set on the wild Yorkshire moors.", summary: "On the Yorkshire moors, Heathcliff — a foundling of mysterious origin — and Catherine Earnshaw grow up together and form a bond that transcends ordinary love. When Catherine chooses to marry the wealthy Edgar Linton instead, Heathcliff disappears for three years and returns a gentleman — but one consumed by revenge that will extend across two generations of both families. Brontë's only novel is one of the strangest and most powerful in the English language: its love story is not tender but savage, its hero a figure of genuine cruelty, its emotional landscape as wild as its setting. It has generated more critical debate than almost any other Victorian novel." },
  { title: "Jane Eyre", author: "Charlotte Bronte", genre: "Classic", mood: "Romantic", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780141441146-L.jpg", description: "An orphan girl becomes a governess and falls in love with her brooding master, Mr. Rochester.", summary: "Jane Eyre, orphaned and mistreated as a child, grows into a young woman of fierce independence and moral integrity. Hired as governess at Thornfield Hall, she falls in love with the brooding Mr. Rochester — but discovers that Thornfield holds a terrible secret in its attic. Brontë's novel is a landmark in the history of the novel's exploration of interiority, with Jane's first-person voice one of the most vivid in literature. It is also a proto-feminist text, insisting on the equal worth and feelings of a poor, plain governess against every social convention of her time. The Gothic mystery and romance remain irresistible." },
  { title: "The Odyssey", author: "Homer", genre: "Classic", mood: "Adventure", rating: 4.5, image: "https://covers.openlibrary.org/b/isbn/9780140268867-L.jpg", description: "The epic journey of Odysseus trying to return home after the Trojan War.", summary: "It takes Odysseus ten years to travel from Troy to his home in Ithaca after the fall of Troy — years during which he encounters Cyclops, Sirens, a goddess who turns men to swine, the dead in the underworld, and the island of the sun god. Meanwhile, his wife Penelope holds off a hundred suitors and his son Telemachus searches for him. Homer's epic is the foundational text of Western literature, the source of the hero's journey narrative pattern, and one of the most direct expressions of what it means to long for home. It reads as freshly today as any contemporary adventure story." },
  { title: "Of Mice and Men", author: "John Steinbeck", genre: "Classic", mood: "Emotional", rating: 4.4, image: "https://covers.openlibrary.org/b/isbn/9780140177398-L.jpg", description: "Two migrant workers dream of a better life in Depression-era California — a timeless story of friendship and loss.", summary: "George Milton and Lennie Small are itinerant ranch workers in Depression-era California, moving from job to job. George is sharp and streetwise; Lennie is physically powerful but mentally disabled and incapable of knowing his own strength. Their shared dream — a small farm of their own, with rabbits for Lennie to tend — sustains them through the hard work and loneliness of their lives. Steinbeck's novella is one of the most economical and devastating works in American literature, a story about the fragility of dreams and the price of loyalty that moves from comedy to tragedy with heartbreaking efficiency." },
];

/* ========================
   STATE
======================== */
const BOOKS_PER_PAGE = 6;
let filteredBooks = [];
let currentPage   = 1;

/* ========================
   DOM REFS
======================== */
const genreFilter    = document.getElementById('genreFilter');
const moodFilter     = document.getElementById('moodFilter');
const ratingFilter   = document.getElementById('ratingFilter');
const searchInput    = document.getElementById('searchInput');
const sortFilter     = document.getElementById('sortFilter');
const recommendBtn   = document.getElementById('recommendBtn');
const loader         = document.getElementById('loader');
const resultsHeader  = document.getElementById('resultsHeader');
const resultCount    = document.getElementById('resultCount');
const savedPref      = document.getElementById('savedPref');
const bookGrid       = document.getElementById('bookGrid');
const noResults      = document.getElementById('noResults');
const pagination     = document.getElementById('pagination');
const darkToggle     = document.getElementById('darkToggle');
const themeIcon      = document.getElementById('themeIcon');
const modal          = document.getElementById('modal');
const modalClose     = document.getElementById('modalClose');
const modalBackdrop  = document.getElementById('modalBackdrop');
const modalBody      = document.getElementById('modalBody');

/* ========================
   THEME
======================== */
function applyTheme(theme) {
  document.body.classList.toggle('dark',  theme === 'dark');
  document.body.classList.toggle('light', theme === 'light');
  if (themeIcon) themeIcon.textContent = theme === 'dark' ? '☀️' : '🌙';
}
const savedTheme = localStorage.getItem('pageturner_theme') || 'dark';
applyTheme(savedTheme);

darkToggle && darkToggle.addEventListener('click', () => {
  const next = document.body.classList.contains('dark') ? 'light' : 'dark';
  applyTheme(next);
  localStorage.setItem('pageturner_theme', next);
});

/* ========================
   SESSION / USER MENU
======================== */
function getSession() {
  return JSON.parse(
    localStorage.getItem('pt_session') ||
    sessionStorage.getItem('pt_session') ||
    'null'
  );
}

function initUserMenu() {
  const session      = getSession();
  const userMenu     = document.getElementById('userMenu');
  const loginLink    = document.getElementById('loginLink');
  const userAvatar   = document.getElementById('userAvatar');
  const userName     = document.getElementById('userName');
  const dropdownInfo = document.getElementById('dropdownInfo');
  const logoutBtn    = document.getElementById('logoutBtn');

  if (!session) {
    if (userMenu)  userMenu.style.display = 'none';
    if (loginLink) loginLink.classList.remove('hidden');
    return;
  }

  const initials = (session.firstName[0] + session.lastName[0]).toUpperCase();
  if (userAvatar)    userAvatar.textContent = initials;
  if (userName)      userName.textContent   = session.firstName;
  if (dropdownInfo)  dropdownInfo.innerHTML = `
    <strong>${session.firstName} ${session.lastName}</strong>
    <span>${session.email}</span>
    ${session.favGenre ? `<span>📚 ${session.favGenre}</span>` : ''}
  `;

  userMenu && userMenu.addEventListener('click', e => {
    e.stopPropagation();
    document.getElementById('userDropdown').classList.toggle('open');
  });
  document.addEventListener('click', () => {
    const dd = document.getElementById('userDropdown');
    if (dd) dd.classList.remove('open');
  });

  logoutBtn && logoutBtn.addEventListener('click', () => {
    localStorage.removeItem('pt_session');
    sessionStorage.removeItem('pt_session');
    window.location.href = 'login.html';
  });

  // Pre-fill genre from user preferences
  if (session.favGenre && genreFilter) {
    genreFilter.value = session.favGenre;
  }
}

/* ========================
   PREFERENCES
======================== */
function loadPreferences() {
  const prefs = JSON.parse(localStorage.getItem('pageturner_prefs') || '{}');
  if (prefs.genre  && genreFilter)  genreFilter.value  = prefs.genre;
  if (prefs.mood   && moodFilter)   moodFilter.value   = prefs.mood;
  if (prefs.rating && ratingFilter) ratingFilter.value = prefs.rating;
}

/* ========================
   STARS
======================== */
function renderStars(rating, large = false) {
  const full  = Math.floor(rating);
  const half  = rating % 1 >= 0.5;
  const empty = 5 - full - (half ? 1 : 0);
  const cls   = large ? 'star large' : 'star';
  let h = '';
  for (let i = 0; i < full;  i++) h += `<span class="${cls} filled">★</span>`;
  if (half)                        h += `<span class="${cls} filled">½</span>`;
  for (let i = 0; i < empty; i++) h += `<span class="${cls}">★</span>`;
  return h;
}

/* ========================
   BOOK CARD
======================== */
function createCard(book, i) {
  const card     = document.createElement('article');
  card.className = 'book-card';
  card.style.animationDelay = `${(i % BOOKS_PER_PAGE) * 0.06}s`;
  const fallback = `https://via.placeholder.com/300x450/1a1a20/e8a838?text=${encodeURIComponent(book.title)}`;

  card.innerHTML = `
    <img class="book-cover" src="${book.image}" alt="${book.title}" loading="lazy"
         onerror="this.src='${fallback}'"/>
    <div class="book-info">
      <span class="book-genre-tag">${book.genre}</span>
      <h3 class="book-title">${book.title}</h3>
      <p class="book-author">by ${book.author}</p>
      <div class="book-stars">
        ${renderStars(book.rating)}
        <span class="book-rating-num">${book.rating.toFixed(1)}</span>
      </div>
      <button class="read-more-btn">Read More</button>
    </div>
  `;

  card.querySelector('.read-more-btn').addEventListener('click', e => { e.stopPropagation(); openModal(book); });
  card.addEventListener('click', () => openModal(book));
  return card;
}

/* ========================
   RENDER PAGE
======================== */
function renderPage(page) {
  currentPage = page;
  const slice = filteredBooks.slice((page - 1) * BOOKS_PER_PAGE, page * BOOKS_PER_PAGE);
  bookGrid.innerHTML = '';
  slice.forEach((b, i) => bookGrid.appendChild(createCard(b, i)));
  renderPagination();
  document.getElementById('resultsSection').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

/* ========================
   PAGINATION
======================== */
function renderPagination() {
  const pages = Math.ceil(filteredBooks.length / BOOKS_PER_PAGE);
  if (pages <= 1) { pagination.classList.add('hidden'); return; }
  pagination.classList.remove('hidden');
  pagination.innerHTML = '';

  const prev = document.createElement('button');
  prev.className = 'page-btn'; prev.textContent = '‹'; prev.disabled = currentPage === 1;
  prev.addEventListener('click', () => renderPage(currentPage - 1));
  pagination.appendChild(prev);

  for (let p = 1; p <= pages; p++) {
    const btn = document.createElement('button');
    btn.className = 'page-btn' + (p === currentPage ? ' active' : '');
    btn.textContent = p;
    btn.addEventListener('click', () => renderPage(p));
    pagination.appendChild(btn);
  }

  const next = document.createElement('button');
  next.className = 'page-btn'; next.textContent = '›'; next.disabled = currentPage === pages;
  next.addEventListener('click', () => renderPage(currentPage + 1));
  pagination.appendChild(next);
}

/* ========================
   SIMILAR BOOKS
======================== */
function getSimilarBooks(book, count = 4) {
  const scored = BOOKS
    .filter(b => b.title !== book.title)
    .map(b => {
      let score = 0;
      if (b.genre === book.genre)  score += 3;   // same genre — strong signal
      if (b.mood  === book.mood)   score += 2;   // same mood
      const ratingDiff = Math.abs(b.rating - book.rating);
      if (ratingDiff <= 0.3)       score += 2;   // similar quality
      else if (ratingDiff <= 0.8)  score += 1;
      if (b.author === book.author) score += 1;  // same author
      // small deterministic tie-breaker so result order is stable
      score += (b.rating / 10);
      return { book: b, score };
    })
    .sort((a, b) => b.score - a.score)
    .slice(0, count)
    .map(s => s.book);
  return scored;
}

/* ========================
   PREVIEW TEXT GENERATOR
======================== */
function generatePreviewPages(book) {
  const previews = {
    "The Midnight Library": [
      `Between life and death there is a library, and within that library, the shelves go on forever. Every book provides a chance to try another life you could have lived. To see how things would be if you had made other choices. Would you have done anything different, if you had the chance to undo your regrets?\n\nNora Seed finds herself in exactly this position. The Midnight Library stands before her, vast and green-lit, smelling of old paper and possibility. Mrs. Elm, her school librarian, sits behind the desk — older now, but still wearing that same knowing smile.\n\n"Every book in this library is a life," Mrs. Elm says, placing her pale hands flat on the desk. "Your life, as it could have been. All you have to do is choose."`,
      `Nora pulled a book from the shelf at random. Its cover was plain green, like all the others, but her name was printed on the spine in small gold letters: NORA SEED. Her fingers trembled as she opened the first page.\n\nThe words swam before her eyes. She saw herself in another city — Montreal, the book told her — living in a bright apartment with a cat named Voltaire and a shelf full of philosophy texts. She had a boyfriend named Luc who made terrible jokes about Descartes. She had not drowned herself in the life-ending sadness that had brought her here.\n\nShe was happy. Or something close to it. The kind of ordinary content that doesn't feel remarkable until you're standing in a library between worlds, reading about a life you could have had.`,
      `"How do I know which life to choose?" Nora asked.\n\nMrs. Elm tilted her head, considering. "You don't. That's rather the point. You try. You live. You feel what each life has to offer." She gestured toward the infinite shelves. "You have until the library closes. When the books go dark, so do you."\n\nNora pulled another book. This one showed her as a glaciologist in Arctic Norway, studying ice cores that held the memory of centuries. Her hands were rough and capable. She woke each morning to the smell of tundra and coffee, and she felt — here was the strange thing — she felt needed. Not lonely in the vast white wilderness, but connected to the oldest stories the earth had to tell.\n\nShe closed the book. She opened another. She began to understand that her regrets had always been pointing her somewhere.`,
      `The library began to change. The lights flickered. Somewhere deep between the shelves, Nora could hear the creak of the building adjusting, as if it were alive and restless.\n\nShe sat on the floor with three open books around her, comparing lives like you might compare train timetables. Here she had become an Olympic swimmer. There she had stayed with Dan and they had moved to the countryside and raised sheep. In another she had gone to Australia at twenty-two and never come back, and she had stood on Bondi Beach at thirty-five watching surfers cut through turquoise water with her heart so full she could barely breathe.\n\n"Which is the right one?" she whispered to no one.\n\nBut that was the thing about lives. You could not choose the right one from the outside. You had to step inside and feel the walls. You had to breathe the air of a life before you knew if you could call it yours.`
    ],
    "The Alchemist": [
      `The boy's name was Santiago. He had a flock of sheep, a rolled-up jacket for a pillow, and a recurring dream about a child who led him to the Egyptian pyramids. He slept in the ruins of a church beneath a sycamore tree, and when he woke before dawn with his heart pounding from the dream, he looked at his sheep and wondered why they had never learned to read omens.\n\nSheep, he had decided, do not dream about treasure. They dream about grass. But then, he supposed, he was the shepherd. Dreaming on their behalf was his responsibility.`,
      `In the village market of Tarifa, he met an old man who sat on a bench and claimed to be the King of Salem. The old man's name was Melchizedek, and he wore a breastplate studded with stones that caught the afternoon light like fire.\n\n"You have a dream," the old man said. Not a question.\n\n"Everyone dreams," Santiago replied carefully.\n\n"Not everyone follows it." Melchizedek smiled and drew a line in the sand with his finger. "There is a language that transcends all languages. It is the language of the universe, of the soul. When you want something, all the universe conspires in helping you to achieve it. This is the Soul of the World."\n\nSantiago thought about his flock. He thought about the book he had been reading, the one he could not finish, and the girl with dark eyes he hoped to see again in the spring.`,
      `He sold his sheep and bought passage on a ship to Africa. The crossing was rough and short and he arrived in Tangier with no language and very little money. By noon on his first day, a stranger had stolen everything.\n\nHe sat in the marketplace surrounded by the noise of a world he did not understand, and he thought: I am an absolute fool. I left everything I knew for a dream a sycamore tree gave me. Melchizedek has probably told the same story to a thousand wandering boys and taken their gold coins gladly.\n\nBut he had said something else, too, the old king. He had said: "When you can't go back, you have to worry only about the best way of moving forward."`,
      `The desert was patient with him. He worked in the crystal shop for nearly a year, watching caravans pass, watching the Englishman read his thick books on alchemy, watching the merchant's eyes grow both sad and satisfied whenever a sale was made. He learned the language of trade and the language of waiting.\n\nThe girl from the oasis — Fatima — sat by the well each morning and he thought about her in the long quiet evenings when the desert wind turned the lantern flames sideways. He thought: here is a life. Here is something I could choose. And it would be a good life. The crystal shop, the desert, Fatima.\n\nBut the wind said something different. The wind said: your Personal Legend is not finished yet. And Santiago, for better or worse, had learned to listen to the wind.`
    ]
  };

  // Default preview generator for books without specific previews
  if (previews[book.title]) return previews[book.title];

  // Generate atmospheric preview pages dynamically
  const genre = book.genre;
  const mood = book.mood;
  const authorLast = book.author.split(' ').pop();

  const openings = {
    Fiction: [
      `There are moments in a person's life that divide everything into before and after. ${book.author} understood this the way a surgeon understands anatomy — not as metaphor but as fact, as something that happens in the body and leaves a mark.\n\nThe story that follows begins at one of those moments. The exact time is unimportant. What matters is what the character does next, and what they discover about themselves when there is no longer anything to hide behind.\n\nThis is a novel about the distances between people, and the impossible, necessary work of crossing them.`,
      `The first chapter begins in the middle of something. That is how lives are lived — not from tidy beginnings but from middles, from the thick of things, from kitchens and arguments and Tuesday mornings when the world decides to change without warning.\n\n${book.title} does not announce its intentions early. It simply begins, as all honest fiction does, with a person in a room, and a question that has no comfortable answer.`
    ],
    Fantasy: [
      `The world had rules that most people chose not to see. That was the first thing the old woman told her apprentice, the morning after the winter solstice, when the air tasted of iron and possibility.\n\n"Magic is not a gift," she said, setting a clay cup of bitter tea on the stone table. "It is a conversation. You speak, and the world speaks back. The question is whether you are willing to hear what it says."\n\nIn the world of ${book.title}, the answer would cost everything. It always does.`,
      `The maps of the old empire showed three hundred cities and named nine hundred rivers. They did not show what lived in the spaces between: the hollow places under the mountains where the light had a different quality, where the shadows arrived a moment before the sun moved, where careful travelers had always chosen to walk quickly and keep their eyes straight.\n\n${book.author} built this world the way cartographers once built worlds — with love for what can be charted, and deep respect for what cannot.`
    ],
    Thriller: [
      `The call came at 3:17 in the morning, the way the worst calls always do — in the hours when the body is most honest about its fears, when the ordinary armour of daylight has been put away.\n\nDetective Sarah Lund (the number would later be checked, rechecked, noted in the case file) had been awake for twenty-two hours. She had been awake, in one sense, for much longer than that.\n\n"You need to come now," the voice on the phone said. And she understood from the sound of it that something had already been broken beyond the possibility of repair.`,
      `Nothing about the crime scene made sense. That was the first clue, although no one recognized it as such for another six days. The second clue was hiding in the evidence they chose not to look at. The third was standing in front of them the entire time, patient as a lie.\n\n${book.title} is a novel about the architecture of deception — how it is built, how it is maintained, and what happens when the wrong person starts asking the right questions.`
    ],
    Romance: [
      `She had made a list of all the reasons it was a bad idea. The list was thorough, specific, and completely convincing. She kept it in her phone under a folder called "Practical Considerations." She added to it whenever she felt the particular danger of his smile.\n\nThe list had seventeen items and had done absolutely nothing to help.\n\n${book.title} is a story about the small, catastrophic failures of common sense, and the remarkable things that grow in the spaces where sense gives out.`,
      `The problem with falling in love — the real problem, not the one people talk about at dinner parties — is that it rearranges your sense of what is normal. Things that were ordinary become significant. A cup of coffee placed exactly the way you like it. A joke that lands because someone has been paying attention. The particular sound of a laugh you'd recognize anywhere.\n\nBy the time you realize it's happened, the rearrangement is complete.`
    ],
    "Self-Help": [
      `Every significant change in a human life begins with a single decision. Not a grand resolution or a moment of dramatic revelation — those rarely stick. Instead, it begins with a quiet, private moment of choosing differently. Of putting the phone down. Of taking the stairs. Of saying yes when fear says no.\n\nThis book is about those moments, and the architecture of habit that either supports or undermines them. The research behind it spans decades and crosses disciplines. But the truth it arrives at is simple enough to carry in a sentence:\n\nYou become what you repeatedly do. The question is whether you are choosing it.`,
      `The ancient Stoics had a practice called memento mori — the deliberate contemplation of death, not to cultivate despair, but to sharpen gratitude for the present. Marcus Aurelius, Emperor of Rome, wrote his private journal not to be published but to remind himself, daily, of what mattered.\n\nThis book borrows that spirit. Not the grimness, but the discipline. The daily practice of asking: what is within my control, and what is not? And then, having answered honestly — acting accordingly.`
    ],
    "Science Fiction": [
      `Three hundred years after the collapse of the global internet, historians argued about what had really been lost. The data, obviously. But also the particular quality of human attention that had been shaped by it — restless, fragmented, hungry for novelty, never quite present.\n\nOn the colony ship Meridian, no one remembered the internet. That was considered a mercy.\n\n${book.title} begins in this future, aboard this ship, with a woman named Kira who discovers something in the recycled water supply that should not exist. The implications, she would later understand, were larger than the ship. Larger than the colony. Larger than humanity's comfortable story about its place in the universe.`,
      `The signal arrived on a Tuesday, which felt somehow wrong. Big discoveries should arrive on significant days — on solstices, on the anniversaries of other discoveries, on mornings when the light has an unusual quality.\n\nInstead: Tuesday. Overcast. The researcher was eating a sandwich.\n\nThe signal was seventeen seconds long and repeated every four hours. It was not, despite initial hopes, a greeting. It was something considerably stranger than that. And the question of what to do about it would divide the world along lines no one had previously known existed.`
    ],
    Historical: [
      `The year the story begins, no one had any reason to believe the world was about to change. That is almost always how it works. People live their ordinary lives — going to markets, arguing about prices, falling in love in inconvenient places — right up until the moment history decides to reveal itself.\n\n${book.title} takes place in that moment of revelation. Its characters are not aware they are living through history. They are simply living. That is what makes their choices so extraordinary, and so human.`,
      `The archive that preserved these documents was discovered by accident, in the basement of a building that had been scheduled for demolition. The papers were water-damaged and required two years of careful restoration before they could be read.\n\nWhat they revealed was a story that the official histories had chosen not to tell — not out of malice, necessarily, but out of the very human desire to simplify, to find the clean narrative inside the messy truth.\n\nThis is the messy truth.`
    ],
    Mystery: [
      `The body was found at 6:43 in the morning, before the coffee had finished brewing, which seemed to Inspector Wren an indecent time for a murder. She had said as much, quietly, to her sergeant, who had not found it funny.\n\nNothing about the scene was immediately obvious. The room was tidy. The windows were locked from the inside. There was no sign of struggle, no indication of forced entry, nothing to suggest that the person who had died had done anything other than sit down and stop being alive.\n\nIt was, Wren thought, the most deliberate nothing she had ever seen. Someone had worked very hard to make it look like this.`,
      `The mystery, at its core, was about what people are willing to protect and what they are willing to sacrifice. The body was almost incidental — a consequence of something that had started years earlier, in a room no one now remembered, between people who had since told themselves convincing stories about why it hadn't really been their fault.\n\n${book.title} is interested in those stories. In the gap between what happened and what people say happened. In the extraordinary human capacity for self-deception, and the few individuals stubborn enough — or damaged enough — to keep looking for the truth beneath.`
    ],
    Biography: [
      `Looking back, it is tempting to find inevitability in the story. The early signs that this was someone unusual. The formative moments that point clearly toward what would come. But the honest truth of every life is that it contains no such arrows. There are only choices, made under conditions of incomplete information, with consequences no one could have predicted.\n\nThis is the honest attempt to reconstruct such a life — not the myth, but the person inside the myth.`,
      `They said later that the success had been obvious from the beginning. They said they had always known. They said the talent was undeniable, the drive extraordinary, the outcome almost inevitable.\n\nThey were wrong, of course. As they almost always are. The people who change things don't look inevitable at the start. They look obstinate, impractical, and frequently unemployable. The difference between them and everyone else is not talent. It is a specific, sometimes maddening refusal to accept the world as it is.`
    ],
    Horror: [
      `The house had been standing for a hundred and twenty years, and in that time it had watched families arrive with optimism and leave with something missing from their faces. The realtor did not mention this. The listing did not mention it either. It mentioned original hardwood floors, a recently updated kitchen, and exceptional natural light.\n\nAll of these things were true. The house had exceptional natural light during the day. At night, it had something else.\n\nThe new family moved in on a Saturday. The children were delighted by the attic.`,
      `There is a theory that fear is simply information. The body detecting a threat and sending a signal. The appropriate response to that signal is to leave.\n\nCharacters in horror novels rarely leave. This is why we read horror novels — to watch people ignore exactly the information we would also ignore, to pretend that we would be different, that we would hear the sound in the basement and choose not to go down, while knowing perfectly well that we are the kind of people who go down.\n\nWe are always the kind of people who go down.`
    ],
    Philosophy: [
      `The question that animates this work is simple to state and impossible to answer in any final way: How should one live?\n\nNot how should one succeed, or prosper, or be remembered — though these questions are not irrelevant. But how, in the daily texture of an ordinary existence, should a person choose to spend their hours, their attention, their care?\n\nThis is the oldest question philosophy asks. It is also the most urgent.`,
      `Plato believed that the unexamined life was not worth living. This was a bold claim, and not without its critics — there are many perfectly pleasant lives lived with very little examination, and many miserable ones devoted to nothing else.\n\nBut there is something in the core of the claim that survives scrutiny. Not that examination guarantees happiness, but that without it, we are living someone else's story. We are running someone else's code, inherited from parents and culture and accident, never quite asking whether it takes us where we actually want to go.`
    ],
    Classic: [
      `It is a truth universally acknowledged — or so they say. But the truths in great literature are rarely universal in the sense of being obvious. They are universal in the sense of being deeply particular: so specific to one place and time and person that, by some mysterious alchemy, they become recognizable to everyone.\n\nThis is a classic for that reason. Not because it is old. Because it is true in that deep, particular way. Because the world it describes, however different from our own, contains people we recognize with a shock that is almost like grief.\n\nIt asks you to read carefully. It rewards the effort.`,
      `The novel was not well received on first publication. The critics found it strange, or too long, or too short, or morally troubling, or not troubling enough. This is what critics have always done with work that turns out to matter.\n\nA hundred years later, we have the advantage of knowing what it turned out to mean. We can see the shadow it cast forward through literature, the conversations it started that are still continuing. We can see, most importantly, the human truth it captured — the one that refused to age because it was not about its time. It was about us.`
    ]
  };

  const genreOpenings = openings[genre] || openings['Fiction'];
  const page1 = genreOpenings[0];
  const page2 = genreOpenings[1] || genreOpenings[0];

  const middle1 = `The pages that follow are careful in the way that great writing is always careful — not precious, not labored, but attentive. ${authorLast} notices the things that other writers walk past. A gesture. A hesitation. The specific quality of silence in a particular room.\n\nThis is a novel that trusts its readers. It does not explain everything. It leaves space for you to bring your own experience, your own losses, your own understanding of the particular difficulty of being a person in the world. That trust is one of the things that makes it worth reading.\n\nThere are books you consume, and books that consume you. ${book.title} belongs to the second category.`;

  const middle2 = `By this point in the story, you will have noticed that ${authorLast} is doing something unusual with structure. The conventional shape — problem, escalation, resolution — is present, but it has been disturbed, tilted at an angle that makes everything slightly unfamiliar.\n\nThis is not a puzzle to be solved. It is a strategy: to prevent the reader from arriving too easily at their own conclusions, from deciding too early what the book is about and settling back comfortably with their assumptions.\n\n${book.title} does not let you settle. It keeps asking you to look again. To reconsider. To notice what you thought you understood.\n\nThe story continues with this same restless intelligence — the quality of a mind that cannot leave anything alone until it is sure it has understood it properly. Whether or not it ever does is something the ending will address, in its own way, on its own terms. `;

  return [page1, page2, middle1, middle2];
}

/* ========================
   MODAL
======================== */
function openModal(book) {
  const fallback = `https://via.placeholder.com/640x300/1a1a20/e8a838?text=${encodeURIComponent(book.title)}`;
  const previewPages = generatePreviewPages(book);
  let currentPreviewPage = 0;

  const amazonQuery = encodeURIComponent(`${book.title} ${book.author}`);
  const buyUrl = `https://www.amazon.com/s?k=${amazonQuery}`;

  // Build similar books HTML
  const similar = getSimilarBooks(book, 4);
  const similarHTML = similar.map(s => {
    const sFallback = `https://via.placeholder.com/80x120/1a1a20/e8a838?text=${encodeURIComponent(s.title)}`;
    return `
      <div class="similar-book-card" data-title="${s.title}">
        <img class="similar-book-cover" src="${s.image}" alt="${s.title}" onerror="this.src='${sFallback}'"/>
        <div class="similar-book-info">
          <p class="similar-book-title">${s.title}</p>
          <p class="similar-book-author">by ${s.author}</p>
          <div class="similar-book-meta">
            <span class="tag tag-genre" style="font-size:0.7rem;padding:0.15rem 0.5rem">${s.genre}</span>
            <span class="similar-rating">★ ${s.rating.toFixed(1)}</span>
          </div>
        </div>
      </div>
    `;
  }).join('');

  const summaryText = book.summary || book.description;

  modalBody.innerHTML = `
    <div class="modal-tabs">
      <button class="modal-tab active" data-tab="overview">📖 Overview</button>
      <button class="modal-tab" data-tab="summary">📝 Summary</button>
      <button class="modal-tab" data-tab="preview">📄 Read Preview</button>
    </div>

    <!-- OVERVIEW TAB -->
    <div class="modal-tab-content" id="tabOverview">
      <img class="modal-cover" src="${book.image}" alt="${book.title}" onerror="this.src='${fallback}'"/>
      <div class="modal-genre-mood">
        <span class="tag tag-genre">${book.genre}</span>
        <span class="tag tag-mood">${book.mood}</span>
      </div>
      <h2 class="modal-title">${book.title}</h2>
      <p class="modal-author">by ${book.author}</p>
      <div class="modal-stars">
        ${renderStars(book.rating, true)}
        <span class="book-rating-num" style="font-size:1rem;margin-left:.4rem">${book.rating.toFixed(1)} / 5</span>
      </div>
      <p class="modal-description">${book.description}</p>
      <a href="${buyUrl}" target="_blank" rel="noopener noreferrer" class="buy-btn">
        🛒 Purchase Book
      </a>
      <div class="similar-section">
        <h4 class="similar-heading">📚 You Might Also Like</h4>
        <div class="similar-books-grid">${similarHTML}</div>
      </div>
    </div>

    <!-- SUMMARY TAB -->
    <div class="modal-tab-content hidden" id="tabSummary">
      <div class="summary-header">
        <img class="modal-cover" src="${book.image}" alt="${book.title}" onerror="this.src='${fallback}'" style="max-height:200px;object-fit:cover"/>
        <div>
          <h2 class="modal-title">${book.title}</h2>
          <p class="modal-author">by ${book.author}</p>
          <div class="modal-stars">${renderStars(book.rating, true)}<span class="book-rating-num" style="font-size:1rem;margin-left:.4rem">${book.rating.toFixed(1)} / 5</span></div>
        </div>
      </div>
      <div class="summary-body">
        <h4 class="summary-label">📖 What This Book Is About</h4>
        <p class="summary-text">${summaryText}</p>
      </div>
      <a href="${buyUrl}" target="_blank" rel="noopener noreferrer" class="buy-btn">
        🛒 Purchase Book
      </a>
      <div class="similar-section">
        <h4 class="similar-heading">📚 You Might Also Like</h4>
        <div class="similar-books-grid">${similarHTML}</div>
      </div>
    </div>

    <!-- PREVIEW TAB -->
    <div class="modal-tab-content hidden" id="tabPreview">
      <div class="preview-header">
        <h2 class="modal-title" style="margin-bottom:0.2rem">${book.title}</h2>
        <p class="modal-author" style="margin-bottom:1.2rem">by ${book.author}</p>
        <div class="preview-notice">📚 Sample Preview — ${previewPages.length} pages</div>
      </div>
      <div class="reader-container">
        <div class="reader-page-indicator">
          Page <span id="previewPageNum">1</span> of ${previewPages.length}
        </div>
        <div class="reader-text" id="readerText"></div>
        <div class="reader-nav">
          <button class="reader-btn" id="prevPageBtn" disabled>← Previous</button>
          <div class="reader-dots" id="readerDots"></div>
          <button class="reader-btn" id="nextPageBtn">Next →</button>
        </div>
      </div>
      <div class="preview-buy-section">
        <p class="preview-buy-teaser">Enjoying the preview? Get the full book today.</p>
        <a href="${buyUrl}" target="_blank" rel="noopener noreferrer" class="buy-btn">
          🛒 Purchase Book
        </a>
      </div>
      <div class="similar-section">
        <h4 class="similar-heading">📚 You Might Also Like</h4>
        <div class="similar-books-grid">${similarHTML}</div>
      </div>
    </div>
  `;

  // Tab switching
  modalBody.querySelectorAll('.modal-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      modalBody.querySelectorAll('.modal-tab').forEach(t => t.classList.remove('active'));
      modalBody.querySelectorAll('.modal-tab-content').forEach(c => c.classList.add('hidden'));
      tab.classList.add('active');
      const map = { overview: 'tabOverview', summary: 'tabSummary', preview: 'tabPreview' };
      document.getElementById(map[tab.dataset.tab]).classList.remove('hidden');
    });
  });

  // Similar book click handlers — open that book's modal
  modalBody.querySelectorAll('.similar-book-card').forEach(card => {
    card.addEventListener('click', () => {
      const found = BOOKS.find(b => b.title === card.dataset.title);
      if (found) { closeModal(); setTimeout(() => openModal(found), 120); }
    });
  });

  // Preview reader logic
  function renderPreviewPage(n) {
    const textEl  = document.getElementById('readerText');
    const numEl   = document.getElementById('previewPageNum');
    const prevBtn = document.getElementById('prevPageBtn');
    const nextBtn = document.getElementById('nextPageBtn');
    const dotsEl  = document.getElementById('readerDots');

    textEl.classList.add('fade-out');
    setTimeout(() => {
      numEl.textContent = n + 1;
      textEl.innerHTML = previewPages[n]
        .split('\n\n')
        .map(p => `<p>${p.trim()}</p>`)
        .join('');
      textEl.classList.remove('fade-out');
      textEl.classList.add('fade-in');
      setTimeout(() => textEl.classList.remove('fade-in'), 400);
    }, 200);

    prevBtn.disabled = n === 0;
    nextBtn.disabled = n === previewPages.length - 1;

    dotsEl.innerHTML = previewPages.map((_, i) =>
      `<span class="reader-dot ${i === n ? 'active' : ''}"></span>`
    ).join('');
    dotsEl.querySelectorAll('.reader-dot').forEach((dot, i) => {
      dot.addEventListener('click', () => { currentPreviewPage = i; renderPreviewPage(i); });
    });
  }

  requestAnimationFrame(() => {
    renderPreviewPage(0);
    document.getElementById('prevPageBtn').addEventListener('click', () => {
      if (currentPreviewPage > 0) { currentPreviewPage--; renderPreviewPage(currentPreviewPage); }
    });
    document.getElementById('nextPageBtn').addEventListener('click', () => {
      if (currentPreviewPage < previewPages.length - 1) { currentPreviewPage++; renderPreviewPage(currentPreviewPage); }
    });
  });

  modal.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}
function closeModal() { modal.classList.add('hidden'); document.body.style.overflow = ''; }

modalClose    && modalClose.addEventListener('click', closeModal);
modalBackdrop && modalBackdrop.addEventListener('click', closeModal);
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });

/* ========================
   FILTER / RECOMMEND
======================== */
function recommend() {
  if (!genreFilter) return;
  const genre     = genreFilter.value.trim();
  const mood      = moodFilter.value.trim();
  const minRating = parseFloat(ratingFilter.value) || 0;
  const query     = searchInput.value.trim().toLowerCase();
  const sort      = sortFilter.value;

  localStorage.setItem('pageturner_prefs', JSON.stringify({ genre, mood, rating: ratingFilter.value }));

  loader.classList.remove('hidden');
  bookGrid.innerHTML = '';
  noResults.classList.add('hidden');
  resultsHeader.classList.add('hidden');
  pagination.classList.add('hidden');

  setTimeout(() => {
    loader.classList.add('hidden');

    filteredBooks = BOOKS.filter(b => {
      const mg = !genre  || b.genre.toLowerCase() === genre.toLowerCase();
      const mm = !mood   || b.mood.toLowerCase()  === mood.toLowerCase();
      const mr = b.rating >= minRating;
      const mq = !query  || b.title.toLowerCase().includes(query) || b.author.toLowerCase().includes(query);
      return mg && mm && mr && mq;
    });

    if (sort === 'title')  filteredBooks.sort((a, b) => a.title.localeCompare(b.title));
    if (sort === 'author') filteredBooks.sort((a, b) => a.author.localeCompare(b.author));
    if (sort === 'rating') filteredBooks.sort((a, b) => b.rating - a.rating);

    if (!filteredBooks.length) { noResults.classList.remove('hidden'); return; }

    resultsHeader.classList.remove('hidden');
    resultCount.textContent = `${filteredBooks.length} book${filteredBooks.length !== 1 ? 's' : ''} found`;
    savedPref.classList.remove('hidden');
    setTimeout(() => savedPref.classList.add('hidden'), 2200);
    renderPage(1);
  }, 600);
}

/* ========================
   EVENTS
======================== */
recommendBtn && recommendBtn.addEventListener('click', recommend);

let dt;
searchInput && searchInput.addEventListener('input', () => { clearTimeout(dt); dt = setTimeout(recommend, 400); });
searchInput && searchInput.addEventListener('keydown', e => { if (e.key === 'Enter') recommend(); });
[genreFilter, moodFilter, ratingFilter, sortFilter].forEach(el => el && el.addEventListener('change', recommend));

/* ========================
   INIT
======================== */
window.addEventListener('DOMContentLoaded', () => {
  initUserMenu();
  loadPreferences();
  filteredBooks = [...BOOKS];
  resultsHeader.classList.remove('hidden');
  resultCount.textContent = `${filteredBooks.length} books available`;
  renderPage(1);
});
